-- ----------------------------
-- Table structure for book_content
-- ----------------------------
DROP TABLE IF EXISTS `book_content`;
CREATE TABLE `book_content`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `book_id` int NOT NULL COMMENT '关联book表id',
  `chapter_number` int NULL DEFAULT NULL COMMENT '章节序号',
  `chapter_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '章节标题',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '章节内容（正文）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_book_id`(`book_id` ASC) USING BTREE,
  CONSTRAINT `fk_book_content_book` FOREIGN KEY (`book_id`) REFERENCES `book` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 237 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of book_content
-- ----------------------------
INSERT INTO `book_content` VALUES (1, 1, 1, '对象导论', '第对象导论\n\n本章深入探讨对象导论的核心概念与实践应用。对象导论是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。无论你是初学者还是有经验的开发者，本章的内容都将为你提供新的视角和深入的理解。我们将从基础概念出发，逐步深入到高级话题，结合大量代码示例和最佳实践，帮助你在实际项目中灵活运用这些知识。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节，只暴露必要的公共接口。继承允许子类复用父类的代码，但应谨慎使用——组合优于继承是广泛认可的设计原则。多态使得同一接口可以有不同的实现，运行时根据对象的实际类型决定调用哪个方法（动态绑定）。\n\nSOLID原则是面向对象设计的五个基本原则：单一职责原则(SRP)——一个类只应该有一个改变的理由；开闭原则(OCP)——对扩展开放，对修改关闭；里氏替换原则(LSP)——子类必须能够替换父类；接口隔离原则(ISP)——不应强迫客户依赖不需要的方法；依赖倒置原则(DIP)——高层模块不应依赖低层模块，都应依赖抽象。\n\n类的设计应该高内聚低耦合。内聚性衡量一个类中各元素的关联程度，高内聚意味着类中的所有方法和属性都为同一个目的服务。耦合度衡量类之间的依赖程度，低耦合意味着修改一个类不需要连锁修改其他类。使用接口和抽象类可以有效降低耦合度。\n\n在实际开发中，对象导论的应用无处不在。优秀的工程师不仅要理解理论知识，更要能够将其灵活运用到实际项目中。以下是一些关键的实践要点：\n\n首先，要深入理解基本原理。很多开发者只知道怎么用，却不知道为什么这样用。理解底层原理能帮助你在遇到问题时快速定位原因，而不是盲目尝试。\n\n其次，要注重代码的可读性和可维护性。写代码不仅是给机器看的，更是给人看的。好的代码应该像散文一样流畅易读。使用有意义的命名，保持函数短小，遵循统一的编码规范。\n\n第三，要善于使用设计模式和最佳实践。前人已经总结了大量的经验和教训，我们没有必要重复发明轮子。但也不要过度设计，简单有效才是最好的方案。\n\n第四，要重视测试。没有测试的代码就是遗留代码。单元测试、集成测试和端到端测试构成了测试金字塔，它们共同保障了代码的质量和系统的稳定性。\n\n进阶话题与最佳实践：\n\n性能优化是每个开发者都需要关注的问题。在对象导论的上下文中，需要注意时间复杂度和空间复杂度的权衡。不要过早优化，但也不要忽视明显的性能问题。使用性能分析工具（profiler）来找出真正的瓶颈，而不是凭直觉猜测。\n\n并发和线程安全也是需要特别关注的领域。在多线程环境下，共享可变状态是万恶之源。尽量使用不可变对象，或者使用适当的同步机制来保护共享数据。Java的并发包（java.util.concurrent）提供了丰富的线程安全工具类。\n\n错误处理策略同样重要。不要吞掉异常，不要用异常来控制正常流程。为可恢复的错误使用受检异常，为编程错误使用运行时异常。提供有意义的错误信息，帮助调用者理解问题所在并采取适当的措施。\n\n最后，持续学习是技术人员的必修课。技术发展日新月异，今天的最佳实践可能明天就过时了。保持好奇心，阅读优秀的开源代码，参与技术社区，不断拓展自己的知识边界。\n\n本章小结：\n对象导论是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解，并能够在实际项目中加以应用。建议结合实际编码练习来巩固所学知识，动手实践是最好的学习方式。');
INSERT INTO `book_content` VALUES (2, 1, 2, '一切都是对象', '第一切都是对象\n\n本章深入探讨一切都是对象的核心概念与实践应用。一切都是对象是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。无论你是初学者还是有经验的开发者，本章的内容都将为你提供新的视角和深入的理解。我们将从基础概念出发，逐步深入到高级话题，结合大量代码示例和最佳实践，帮助你在实际项目中灵活运用这些知识。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节，只暴露必要的公共接口。继承允许子类复用父类的代码，但应谨慎使用——组合优于继承是广泛认可的设计原则。多态使得同一接口可以有不同的实现，运行时根据对象的实际类型决定调用哪个方法（动态绑定）。\n\nSOLID原则是面向对象设计的五个基本原则：单一职责原则(SRP)——一个类只应该有一个改变的理由；开闭原则(OCP)——对扩展开放，对修改关闭；里氏替换原则(LSP)——子类必须能够替换父类；接口隔离原则(ISP)——不应强迫客户依赖不需要的方法；依赖倒置原则(DIP)——高层模块不应依赖低层模块，都应依赖抽象。\n\n类的设计应该高内聚低耦合。\n\n在实际开发中，一切都是对象的应用无处不在。优秀的工程师不仅要理解理论知识，更要能够将其灵活运用到实际项目中。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n一切都是对象是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解，并能够在实际项目中加以应用。建议结合实际编码练习来巩固所学知识，动手实践是最好的学习方式。');
INSERT INTO `book_content` VALUES (3, 1, 3, '操作符', '第操作符\n\n本章深入探讨操作符的核心概念与实践应用。操作符是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。我们将从基础概念出发，逐步深入到高级话题，结合大量代码示例和最佳实践，帮助你在实际项目中灵活运用这些知识。\n\n本节深入讲解操作符的核心知识。在现代软件工程实践中，操作符扮演着不可或缺的角色。深入理解这些概念不仅有助于编写更高质量的代码，还能帮助你在技术面试和实际项目中游刃有余。理论基础是实践的根基。扎实的理论知识能让你在面对复杂问题时有章可循。技术选型是工程决策的重要环节。没有银弹——每种技术都有其适用场景和局限性。持续改进是优秀工程师的习惯。\n\n在实际开发中，操作符的应用无处不在。优秀的工程师不仅要理解理论知识，更要能够将其灵活运用到实际项目中。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n操作符是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解，并能够在实际项目中加以应用。');
INSERT INTO `book_content` VALUES (4, 1, 4, '控制执行流程', '第控制执行流程\n\n本章深入探讨控制执行流程的核心概念与实践应用。控制执行流程是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。我们将从基础概念出发，逐步深入到高级话题，结合大量代码示例和最佳实践，帮助你在实际项目中灵活运用这些知识。\n\n异常处理是保证程序健壮性的重要机制。Java的异常体系以Throwable为根类，分为Error和Exception。Exception又分为受检异常和非受检异常。try-catch-finally结构用于处理异常。Java 7引入了try-with-resources语法，自动管理实现了AutoCloseable接口的资源。异常处理最佳实践：不要用异常控制正常流程；捕获具体的异常类型；提供有意义的错误信息。\n\n在实际开发中，控制执行流程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n控制执行流程是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解，并能够在实际项目中加以应用。');
INSERT INTO `book_content` VALUES (5, 1, 5, '初始化与清理', '第初始化与清理\n\n本章深入探讨初始化与清理的核心概念与实践应用。初始化与清理是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。我们将从基础概念出发，逐步深入到高级话题。\n\n本节深入讲解初始化与清理的核心知识。在现代软件工程实践中，初始化与清理扮演着不可或缺的角色。深入理解这些概念不仅有助于编写更高质量的代码，还能帮助你在技术面试和实际项目中游刃有余。理论基础是实践的根基。技术选型是工程决策的重要环节。持续改进是优秀工程师的习惯。\n\n在实际开发中，初始化与清理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n初始化与清理是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解，并能够在实际项目中加以应用。');
INSERT INTO `book_content` VALUES (6, 1, 6, '访问权限控制', '第访问权限控制\n\n本章深入探讨访问权限控制的核心概念与实践应用。访问权限控制是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n本节深入讲解访问权限控制的核心知识。在现代软件工程实践中，访问权限控制扮演着不可或缺的角色。深入理解这些概念不仅有助于编写更高质量的代码，还能帮助你在技术面试和实际项目中游刃有余。理论基础是实践的根基。技术选型是工程决策的重要环节。持续改进是优秀工程师的习惯。\n\n在实际开发中，访问权限控制的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n访问权限控制是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解。');
INSERT INTO `book_content` VALUES (7, 1, 7, '复用类', '第复用类\n\n本章深入探讨复用类的核心概念与实践应用。复用类是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节。继承允许子类复用父类的代码，但应谨慎使用——组合优于继承是广泛认可的设计原则。多态使得同一接口可以有不同的实现。SOLID原则是面向对象设计的五个基本原则。类的设计应该高内聚低耦合。\n\n在实际开发中，复用类的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n复用类是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解。');
INSERT INTO `book_content` VALUES (8, 1, 8, '多态', '第多态\n\n本章深入探讨多态的核心概念与实践应用。多态是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n本节深入讲解多态的核心知识。在现代软件工程实践中，多态扮演着不可或缺的角色。深入理解这些概念不仅有助于编写更高质量的代码，还能帮助你在技术面试和实际项目中游刃有余。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，多态的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n多态是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解。');
INSERT INTO `book_content` VALUES (9, 1, 9, '接口', '第接口\n\n本章深入探讨接口的核心概念与实践应用。接口是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n本节深入讲解接口的核心知识。在现代软件工程实践中，接口扮演着不可或缺的角色。深入理解这些概念不仅有助于编写更高质量的代码，还能帮助你在技术面试和实际项目中游刃有余。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，接口的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n接口是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解。');
INSERT INTO `book_content` VALUES (10, 1, 10, '内部类', '第内部类\n\n本章深入探讨内部类的核心概念与实践应用。内部类是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节。继承允许子类复用父类的代码。多态使得同一接口可以有不同的实现。SOLID原则是面向对象设计的五个基本原则。类的设计应该高内聚低耦合。\n\n在实际开发中，内部类的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。\n\n本章小结：\n内部类是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解。');
INSERT INTO `book_content` VALUES (11, 1, 11, '集合', '第集合\n\n本章深入探讨集合的核心概念与实践应用。集合是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n本节深入讲解集合的核心知识。在现代软件工程实践中，集合扮演着不可或缺的角色。深入理解这些概念不仅有助于编写更高质量的代码，还能帮助你在技术面试和实际项目中游刃有余。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，集合的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。\n\n本章小结：\n集合是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解。');
INSERT INTO `book_content` VALUES (12, 1, 12, '异常处理', '第异常处理\n\n本章深入探讨异常处理的核心概念与实践应用。异常处理是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n异常处理是保证程序健壮性的重要机制。Java的异常体系以Throwable为根类，分为Error和Exception。Exception又分为受检异常（Checked Exception，必须处理）和非受检异常（Unchecked Exception，即RuntimeException及其子类）。try-catch-finally结构用于处理异常。Java 7引入了try-with-resources语法。异常处理最佳实践：不要用异常控制正常流程；捕获具体的异常类型而非通用Exception；提供有意义的错误信息；不要吞掉异常。\n\n在实际开发中，异常处理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n异常处理是软件开发中的基础且重要的知识领域。通过本章的学习，你应该对其核心概念有了全面的理解。');
INSERT INTO `book_content` VALUES (13, 2, 1, '创建和销毁对象', '第创建和销毁对象\n\n本章深入探讨创建和销毁对象的核心概念与实践应用。创建和销毁对象是软件工程中至关重要的主题，理解并掌握它将显著提升你的编程能力和代码质量。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节。继承允许子类复用父类的代码。多态使得同一接口可以有不同的实现。SOLID原则是面向对象设计的五个基本原则。类的设计应该高内聚低耦合。\n\n在实际开发中，创建和销毁对象的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n创建和销毁对象是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (14, 2, 2, '对所有对象都通用的方法', '第对所有对象都通用的方法\n\n本章深入探讨对所有对象都通用的方法的核心概念与实践应用。对所有对象都通用的方法是软件工程中至关重要的主题。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起。继承允许子类复用父类的代码。多态使得同一接口可以有不同的实现。SOLID原则是面向对象设计的五个基本原则。\n\n在实际开发中，对所有对象都通用的方法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n对所有对象都通用的方法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (15, 2, 3, '类和接口', '第类和接口\n\n本章深入探讨类和接口的核心概念与实践应用。类和接口是软件工程中至关重要的主题。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节。继承允许子类复用父类的代码，但应谨慎使用——组合优于继承。多态使得同一接口可以有不同的实现。SOLID原则是面向对象设计的五个基本原则。类的设计应该高内聚低耦合。\n\n在实际开发中，类和接口的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。\n\n本章小结：\n类和接口是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (16, 2, 4, '泛型', '第泛型\n\n本章深入探讨泛型的核心概念与实践应用。泛型是软件工程中至关重要的主题。\n\n泛型（Generics）是Java 5引入的类型参数化机制，使得类、接口和方法可以操作指定类型的对象，同时保持类型安全。类型擦除：Java泛型是通过类型擦除实现的。通配符：?表示未知类型。上界通配符<? extends T>表示T或T的子类型。下界通配符<? super T>表示T或T的父类型。PECS原则。枚举（Enum）是Java 5引入的特殊类型。注解（Annotation）为代码提供元数据。\n\n在实际开发中，泛型的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n泛型是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (17, 2, 5, '枚举和注解', '第枚举和注解\n\n本章深入探讨枚举和注解的核心概念与实践应用。枚举和注解是软件工程中至关重要的主题。\n\n泛型（Generics）是Java 5引入的类型参数化机制。枚举（Enum）是Java 5引入的特殊类型，比传统的int常量更安全、更强大。每个枚举常量是该枚举类的一个实例。枚举可以有构造器、字段和方法。EnumSet和EnumMap是专门为枚举设计的高效集合类。注解（Annotation）为代码提供元数据。常用内置注解：@Override、@Deprecated、@SuppressWarnings、@FunctionalInterface。\n\n在实际开发中，枚举和注解的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n枚举和注解是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (18, 2, 6, 'Lambda和Stream', '第Lambda和Stream\n\n本章深入探讨Lambda和Stream的核心概念与实践应用。Lambda和Stream是软件工程中至关重要的主题。\n\n函数是代码组织的基本单元。好的函数应该短小、只做一件事、保持同一抽象层级。Lambda表达式和函数式编程：Java 8引入Lambda表达式，使函数成为一等公民。常见的函数式接口包括Function<T,R>、Predicate<T>、Consumer<T>、Supplier<T>。Stream API提供了声明式的数据处理方式，包括map、filter、reduce等操作。函数式编程强调不可变数据和无副作用。高阶函数接受函数作为参数或返回函数作为结果。方法引用是Lambda的简洁形式。\n\n在实际开发中，Lambda和Stream的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nLambda和Stream是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (19, 2, 7, '方法', '第方法\n\n本章深入探讨方法的核心概念与实践应用。方法是软件工程中至关重要的主题。\n\n函数是代码组织的基本单元。好的函数应该短小（理想情况下不超过20行）、只做一件事、保持同一抽象层级。参数设计：参数越少越好。零参函数最理想，一参函数次之。超过三个参数时应考虑将参数封装为对象。布尔参数通常是函数做了两件事的标志，应当拆分为两个函数。\n\n在实际开发中，方法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n方法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (20, 2, 8, '通用编程', '第通用编程\n\n本章深入探讨通用编程的核心概念与实践应用。通用编程是软件工程中至关重要的主题。\n\n本节深入讲解通用编程的核心知识。在现代软件工程实践中，通用编程扮演着不可或缺的角色。理论基础是实践的根基。技术选型是工程决策的重要环节。没有银弹——每种技术都有其适用场景和局限性。持续改进是优秀工程师的习惯。\n\n在实际开发中，通用编程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n通用编程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (21, 2, 9, '异常', '第异常\n\n本章深入探讨异常的核心概念与实践应用。异常是软件工程中至关重要的主题。\n\n异常处理是保证程序健壮性的重要机制。Java的异常体系以Throwable为根类，分为Error和Exception。Exception又分为受检异常和非受检异常。try-catch-finally结构用于处理异常。异常处理最佳实践：不要用异常控制正常流程；捕获具体的异常类型；提供有意义的错误信息；不要吞掉异常。\n\n在实际开发中，异常的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n异常是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (22, 2, 10, '并发', '第并发\n\n本章深入探讨并发的核心概念与实践应用。并发是软件工程中至关重要的主题。\n\n进程是操作系统资源分配的基本单位，线程是CPU调度的基本单位。同步与互斥：临界区问题要求互斥、前进和有限等待。互斥锁(Mutex)保证同一时刻只有一个线程进入临界区。信号量(Semaphore)是更通用的同步工具。Java的并发包（java.util.concurrent）提供了丰富的线程安全工具类。\n\n在实际开发中，并发的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n并发是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (23, 2, 11, '序列化', '第序列化\n\n本章深入探讨序列化的核心概念与实践应用。序列化是软件工程中至关重要的主题。\n\n泛型（Generics）是Java 5引入的类型参数化机制。序列化是将对象转换为字节流以便存储或传输的过程。Java通过Serializable接口支持序列化。注意事项：serialVersionUID的作用、transient关键字排除字段、自定义序列化方法writeObject/readObject。JSON序列化（如Jackson、Gson）是更现代的替代方案。\n\n在实际开发中，序列化的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n序列化是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (24, 3, 1, '数据结构与算法', '第数据结构与算法\n\n本章深入探讨数据结构与算法的核心概念与实践应用。数据结构与算法是软件工程中至关重要的主题。\n\n算法分析是计算机科学的核心。时间复杂度用大O表示法描述算法运行时间随输入规模增长的趋势：O(1)常数时间、O(log n)对数时间、O(n)线性时间、O(n log n)线性对数时间、O(n²)平方时间、O(2ⁿ)指数时间。经典排序算法：冒泡排序O(n²)、插入排序O(n²)、归并排序O(n log n)、快速排序平均O(n log n)、堆排序O(n log n)。查找算法：顺序查找O(n)、二分查找O(log n)、散列表查找平均O(1)。高级算法思想：动态规划、贪心算法、分治法。\n\n在实际开发中，数据结构与算法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。第三，要善于使用设计模式和最佳实践。第四，要重视测试。\n\n本章小结：\n数据结构与算法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (25, 3, 2, '字符串与文本', '第字符串与文本\n\n本章深入探讨字符串与文本的核心概念与实践应用。字符串与文本是软件工程中至关重要的主题。\n\n本节深入讲解字符串与文本的核心知识。在现代软件工程实践中，字符串与文本扮演着不可或缺的角色。深入理解这些概念不仅有助于编写更高质量的代码，还能帮助你在技术面试和实际项目中游刃有余。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，字符串与文本的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n字符串与文本是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (26, 3, 3, '数字日期和时间', '第数字日期和时间\n\n本章深入探讨数字日期和时间的核心概念与实践应用。数字日期和时间是软件工程中至关重要的主题。\n\n本节深入讲解数字日期和时间的核心知识。在现代软件工程实践中，数字日期和时间扮演着不可或缺的角色。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，数字日期和时间的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n数字日期和时间是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (27, 3, 4, '迭代器与生成器', '第迭代器与生成器\n\n本章深入探讨迭代器与生成器的核心概念与实践应用。迭代器与生成器是软件工程中至关重要的主题。\n\n本节深入讲解迭代器与生成器的核心知识。在现代软件工程实践中，迭代器与生成器扮演着不可或缺的角色。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，迭代器与生成器的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n迭代器与生成器是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (28, 3, 5, '文件与IO', '第文件与IO\n\n本章深入探讨文件与IO的核心概念与实践应用。文件与IO是软件工程中至关重要的主题。\n\n存储器层次结构利用了局部性原理来弥合处理器速度和内存速度之间的差距。文件系统将数据组织为文件和目录的层次结构。常见文件系统：ext4（Linux默认）、NTFS（Windows）、APFS（macOS）。文件分配方式：连续分配、链接分配、索引分配。日志文件系统通过写前日志保证崩溃一致性。\n\n在实际开发中，文件与IO的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n文件与IO是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (29, 3, 6, '数据编码与处理', '第数据编码与处理\n\n本章深入探讨数据编码与处理的核心概念与实践应用。数据编码与处理是软件工程中至关重要的主题。\n\n本节深入讲解数据编码与处理的核心知识。在现代软件工程实践中，数据编码与处理扮演着不可或缺的角色。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，数据编码与处理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n数据编码与处理是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (30, 3, 7, '函数式编程', '第函数式编程\n\n本章深入探讨函数式编程的核心概念与实践应用。函数式编程是软件工程中至关重要的主题。\n\n函数是代码组织的基本单元。好的函数应该短小、只做一件事、保持同一抽象层级。Lambda表达式和函数式编程使函数成为一等公民。常见的函数式接口包括Function、Predicate、Consumer、Supplier。Stream API提供了声明式的数据处理方式。函数式编程强调不可变数据和无副作用。高阶函数接受函数作为参数或返回函数作为结果。\n\n在实际开发中，函数式编程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n函数式编程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (31, 3, 8, '类与对象', '第类与对象\n\n本章深入探讨类与对象的核心概念与实践应用。类与对象是软件工程中至关重要的主题。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节。继承允许子类复用父类的代码，但应谨慎使用——组合优于继承。多态使得同一接口可以有不同的实现。SOLID原则是面向对象设计的五个基本原则。类的设计应该高内聚低耦合。\n\n在实际开发中，类与对象的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n类与对象是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (32, 3, 9, '元编程', '第元编程\n\n本章深入探讨元编程的核心概念与实践应用。元编程是软件工程中至关重要的主题。\n\n本节深入讲解元编程的核心知识。在现代软件工程实践中，元编程扮演着不可或缺的角色。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，元编程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n元编程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (33, 3, 10, '模块与包', '第模块与包\n\n本章深入探讨模块与包的核心概念与实践应用。模块与包是软件工程中至关重要的主题。\n\n本节深入讲解模块与包的核心知识。在现代软件工程实践中，模块与包扮演着不可或缺的角色。理论基础是实践的根基。技术选型是工程决策的重要环节。\n\n在实际开发中，模块与包的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n模块与包是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (34, 3, 11, '网络与Web编程', '第网络与Web编程\n\n本章深入探讨网络与Web编程的核心概念与实践应用。网络与Web编程是软件工程中至关重要的主题。\n\n计算机网络采用分层架构。TCP/IP四层模型：应用层（HTTP、FTP、DNS、SMTP）、传输层（TCP、UDP）、网络层（IP、ICMP、ARP）、数据链路层（以太网、WiFi）。TCP协议提供可靠的面向连接的字节流服务。HTTP协议是Web的基础。\n\n在实际开发中，网络与Web编程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n网络与Web编程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (35, 3, 12, '并发编程', '第并发编程\n\n本章深入探讨并发编程的核心概念与实践应用。并发编程是软件工程中至关重要的主题。\n\n进程是操作系统资源分配的基本单位，线程是CPU调度的基本单位。同步与互斥：临界区问题要求互斥、前进和有限等待。互斥锁(Mutex)保证同一时刻只有一个线程进入临界区。信号量(Semaphore)是更通用的同步工具。死锁的四个必要条件：互斥、占有并等待、非抢占、循环等待。\n\n在实际开发中，并发编程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n并发编程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (36, 4, 1, '整洁代码', '第整洁代码\n\n本章深入探讨整洁代码的核心概念与实践应用。整洁代码是软件工程中至关重要的主题。\n\n整洁代码的核心理念：代码是写给人看的，附带能被机器执行。好的代码读起来应该像好散文一样流畅自然。Robert C. Martin定义整洁代码为：优雅高效、直截了当、减少依赖、完善错误处理、只做好一件事。命名的艺术：名称应该揭示意图。避免误导性命名。函数的原则：函数应该短小，理想情况20行以内。函数应该只做一件事。\n\n在实际开发中，整洁代码的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n整洁代码是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (37, 4, 2, '有意义的命名', '第有意义的命名\n\n本章深入探讨有意义的命名的核心概念与实践应用。有意义的命名是软件工程中至关重要的主题。\n\n整洁代码的核心理念：代码是写给人看的。命名的艺术：名称应该揭示意图，如用elapsedTimeInDays而非d。避免误导性命名，不要用accountList除非它真的是List类型。名称应当有意义的区分。类名应该是名词或名词短语（Customer, Account），方法名应该是动词或动词短语（postPayment, deletePage）。\n\n在实际开发中，有意义的命名的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n有意义的命名是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (38, 4, 3, '函数', '第函数\n\n本章深入探讨函数的核心概念与实践应用。函数是软件工程中至关重要的主题。\n\n函数是代码组织的基本单元。好的函数应该短小（理想情况下不超过20行）、只做一件事、保持同一抽象层级。函数命名应当使用动词或动词短语。参数设计：参数越少越好。零参函数最理想，一参函数次之，二参函数再次之。超过三个参数时应考虑将参数封装为对象。布尔参数通常是函数做了两件事的标志，应当拆分为两个函数。\n\n在实际开发中，函数的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n函数是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (39, 4, 4, '注释', '第注释\n\n本章深入探讨注释的核心概念与实践应用。注释是软件工程中至关重要的主题。\n\n整洁代码的核心理念：好代码胜过注释。不要用注释来弥补糟糕的代码。好的注释包括：法律信息注释、提供信息的注释、解释意图的注释、警示注释、TODO注释。坏的注释包括：多余的注释、误导性注释、循规式注释、日志式注释、归属注释、注释掉的代码。\n\n在实际开发中，注释的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n注释是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (40, 4, 5, '格式', '第格式\n\n本章深入探讨格式的核心概念与实践应用。格式是软件工程中至关重要的主题。\n\n整洁代码的核心理念：代码格式关乎沟通。好的格式让代码读起来流畅自然。垂直格式：文件不宜过长，概念相关的代码应该靠近。水平格式：行宽不宜超过120字符。缩进表示层次结构。团队应统一编码风格。\n\n在实际开发中，格式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n格式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (41, 4, 6, '对象和数据结构', '第对象和数据结构\n\n本章深入探讨对象和数据结构的核心概念与实践应用。对象和数据结构是软件工程中至关重要的主题。\n\n面向对象编程的三大特性：封装、继承和多态。封装将数据和行为捆绑在一起，通过访问控制隐藏内部实现细节。对象暴露行为隐藏数据，数据结构暴露数据没有行为。得墨忒耳律（Law of Demeter）：模块不应了解其操纵对象的内部。SOLID原则是面向对象设计的五个基本原则。\n\n在实际开发中，对象和数据结构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n对象和数据结构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (42, 4, 7, '错误处理', '第错误处理\n\n本章深入探讨错误处理的核心概念与实践应用。错误处理是软件工程中至关重要的主题。\n\n异常处理是保证程序健壮性的重要机制。Java的异常体系以Throwable为根类。异常处理最佳实践：不要用异常控制正常流程；捕获具体的异常类型；提供有意义的错误信息；不要吞掉异常（空catch块是大忌）；使用自定义异常类来表示特定的业务错误。\n\n在实际开发中，错误处理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n错误处理是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (43, 4, 8, '边界', '第边界\n\n本章深入探讨边界的核心概念与实践应用。边界是软件工程中至关重要的主题。\n\n本节深入讲解边界的核心知识。在现代软件工程实践中，边界扮演着不可或缺的角色。学习性测试：通过编写测试来探索第三方API的行为。使用适配器模式封装第三方代码，降低耦合。理论基础是实践的根基。\n\n在实际开发中，边界的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n边界是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (44, 4, 9, '单元测试', '第单元测试\n\n本章深入探讨单元测试的核心概念与实践应用。单元测试是软件工程中至关重要的主题。\n\n整洁代码的核心理念：测试代码同样需要整洁。TDD三定律：先写失败的测试、只写刚好失败的测试、只写刚好通过测试的生产代码。FIRST原则：Fast快速、Independent独立、Repeatable可重复、Self-validating自验证、Timely及时。每个测试函数只测一个概念。\n\n在实际开发中，单元测试的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n单元测试是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (45, 4, 10, '类', '第类\n\n本章深入探讨类的核心概念与实践应用。类是软件工程中至关重要的主题。\n\n面向对象编程的三大特性：封装、继承和多态。类应该短小。单一职责原则：类应该只有一个改变的理由。类应该高内聚。开闭原则：对扩展开放，对修改关闭。SOLID原则是面向对象设计的五个基本原则。\n\n在实际开发中，类的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n类是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (46, 4, 11, '系统', '第系统\n\n本章深入探讨系统的核心概念与实践应用。系统是软件工程中至关重要的主题。\n\n本节深入讲解系统的核心知识。在现代软件工程实践中，系统扮演着不可或缺的角色。将构造与使用分开。依赖注入实现控制反转。面向切面编程（AOP）处理横切关注点。系统需要领域特定语言。理论基础是实践的根基。\n\n在实际开发中，系统的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n系统是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (47, 4, 12, '迭进', '第迭进\n\n本章深入探讨迭进的核心概念与实践应用。迭进是软件工程中至关重要的主题。\n\n本节深入讲解迭进的核心知识。简单设计四条规则：运行所有测试、不可重复、表达了程序员的意图、尽可能减少类和方法的数量。通过重构提升设计质量。理论基础是实践的根基。\n\n在实际开发中，迭进的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n迭进是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (48, 5, 1, '引言', '第引言\n\n本章深入探讨引言的核心概念与实践应用。引言是软件工程中至关重要的主题。\n\n本节深入讲解引言的核心知识。在现代软件工程实践中，引言扮演着不可或缺的角色。设计模式是面向对象设计中反复出现的问题的经典解决方案，由GoF在1994年总结为23种模式，分为创建型、结构型和行为型三大类。理论基础是实践的根基。\n\n在实际开发中，引言的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n引言是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (49, 5, 2, '创建型模式概述', '第创建型模式概述\n\n本章深入探讨创建型模式概述的核心概念与实践应用。创建型模式概述是软件工程中至关重要的主题。\n\n设计模式是面向对象设计中反复出现的问题的经典解决方案。创建型模式关注对象创建机制：单例模式确保全局唯一实例；工厂方法定义创建对象的接口由子类决定实例化哪个类；抽象工厂提供创建一系列相关对象的接口；建造者模式将复杂对象的构建与表示分离；原型模式通过克隆现有实例创建新对象。\n\n在实际开发中，创建型模式概述的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n创建型模式概述是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (50, 5, 3, '工厂方法模式', '第工厂方法模式\n\n本章深入探讨工厂方法模式的核心概念与实践应用。工厂方法模式是软件工程中至关重要的主题。\n\n设计模式是面向对象设计中反复出现的问题的经典解决方案。工厂方法模式定义创建对象的接口，由子类决定实例化哪个类。工厂方法让类的实例化延迟到子类。它遵循开闭原则：新增产品时只需新增工厂子类。\n\n在实际开发中，工厂方法模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n工厂方法模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (51, 5, 4, '抽象工厂模式', '第抽象工厂模式\n\n本章深入探讨抽象工厂模式的核心概念与实践应用。抽象工厂模式是软件工程中至关重要的主题。\n\n设计模式是面向对象设计中反复出现的问题的经典解决方案。抽象工厂提供创建一系列相关或相互依赖对象的接口，而无需指定它们具体的类。适用于系统需要独立于产品创建方式的场景。\n\n在实际开发中，抽象工厂模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n抽象工厂模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (52, 5, 5, '单例模式', '第单例模式\n\n本章深入探讨单例模式的核心概念与实践应用。单例模式是软件工程中至关重要的主题。\n\n设计模式是面向对象设计中反复出现的问题的经典解决方案。单例模式确保一个类只有一个实例，并提供全局访问点。适用于配置管理、线程池、缓存等场景。实现方式：饿汉式（类加载时创建）、懒汉式（首次使用时创建）、双重检查锁、枚举单例。\n\n在实际开发中，单例模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n单例模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (53, 5, 6, '建造者模式', '第建造者模式\n\n本章深入探讨建造者模式的核心概念与实践应用。建造者模式是软件工程中至关重要的主题。\n\n设计模式是面向对象设计中反复出现的问题的经典解决方案。建造者模式将复杂对象的构建与表示分离，使得同样的构建过程可以创建不同的表示。适合参数众多的对象创建。链式调用（fluent API）是常见实现方式。\n\n在实际开发中，建造者模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n建造者模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (54, 5, 7, '原型模式', '第原型模式\n\n本章深入探讨原型模式的核心概念与实践应用。原型模式是软件工程中至关重要的主题。\n\n设计模式是面向对象设计中反复出现的问题的经典解决方案。原型模式通过克隆现有实例创建新对象。Java中通过实现Cloneable接口和重写clone()方法实现。注意浅拷贝与深拷贝的区别。\n\n在实际开发中，原型模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n原型模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (55, 5, 8, '适配器模式', '第适配器模式\n\n本章深入探讨适配器模式的核心概念与实践应用。适配器模式是软件工程中至关重要的主题。\n\n结构型模式关注类和对象的组合。适配器模式使接口不兼容的类可以一起工作，如将旧API适配为新接口。分为类适配器（通过继承）和对象适配器（通过组合）。\n\n在实际开发中，适配器模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n适配器模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (56, 5, 9, '装饰器模式', '第装饰器模式\n\n本章深入探讨装饰器模式的核心概念与实践应用。装饰器模式是软件工程中至关重要的主题。\n\n装饰器模式动态地给对象添加职责，如Java IO中的BufferedInputStream。装饰器和被装饰对象实现同一接口。装饰器持有被装饰对象的引用，转发请求并可在前后添加额外行为。\n\n在实际开发中，装饰器模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n装饰器模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (57, 5, 10, '观察者模式', '第观察者模式\n\n本章深入探讨观察者模式的核心概念与实践应用。观察者模式是软件工程中至关重要的主题。\n\n行为型模式关注对象间的通信。观察者模式定义一对多依赖关系，当一个对象状态改变时，所有依赖它的对象都会收到通知并自动更新。Java中的实现：java.util.Observer接口（已废弃），现代方式使用事件监听器或响应式编程。\n\n在实际开发中，观察者模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n观察者模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (58, 5, 11, '策略模式', '第策略模式\n\n本章深入探讨策略模式的核心概念与实践应用。策略模式是软件工程中至关重要的主题。\n\n策略模式定义算法族，使它们可以互相替换。策略模式让算法的变化独立于使用算法的客户。Java 8之后可以用Lambda表达式简化策略模式的实现。\n\n在实际开发中，策略模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n策略模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (59, 5, 12, '模板方法模式', '第模板方法模式\n\n本章深入探讨模板方法模式的核心概念与实践应用。模板方法模式是软件工程中至关重要的主题。\n\n模板方法在父类定义算法骨架，由子类实现具体步骤。钩子方法允许子类选择性地覆盖。模板方法遵循好莱坞原则：不要打电话给我们，我们会打电话给你。Spring框架大量使用模板方法模式，如JdbcTemplate。\n\n在实际开发中，模板方法模式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n模板方法模式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (60, 6, 1, '算法基础', '第算法基础\n\n本章深入探讨算法基础的核心概念与实践应用。算法基础是软件工程中至关重要的主题。\n\n算法分析是计算机科学的核心。时间复杂度用大O表示法描述算法运行时间随输入规模增长的趋势：O(1)常数时间、O(log n)对数时间、O(n)线性时间、O(n log n)线性对数时间、O(n²)平方时间、O(2ⁿ)指数时间。\n\n在实际开发中，算法基础的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n算法基础是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (61, 6, 2, '渐近分析', '第渐近分析\n\n本章深入探讨渐近分析的核心概念与实践应用。渐近分析是软件工程中至关重要的主题。\n\n算法分析是计算机科学的核心。渐近分析关注算法在输入规模趋近无穷时的行为。大O表示法给出上界，大Ω表示法给出下界，大Θ表示法给出紧确界。主定理用于求解递推关系T(n) = aT(n/b) + f(n)的渐近复杂度。\n\n在实际开发中，渐近分析的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n渐近分析是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (62, 6, 3, '分治策略', '第分治策略\n\n本章深入探讨分治策略的核心概念与实践应用。分治策略是软件工程中至关重要的主题。\n\n分治法将大问题分解为相似小问题递归求解。三个步骤：分解、解决、合并。经典应用：归并排序、快速排序、Strassen矩阵乘法、最近点对问题。分治法的时间复杂度通常用主定理求解。\n\n在实际开发中，分治策略的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n分治策略是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (63, 6, 4, '排序算法', '第排序算法\n\n本章深入探讨排序算法的核心概念与实践应用。排序算法是软件工程中至关重要的主题。\n\n经典排序算法：冒泡排序O(n²)通过相邻元素比较交换；插入排序O(n²)适合小规模和近乎有序的数据；归并排序O(n log n)是稳定排序，采用分治策略；快速排序平均O(n log n)是实践中最快的通用排序算法；堆排序O(n log n)基于最大堆/最小堆数据结构。比较排序的下界为O(n log n)。\n\n在实际开发中，排序算法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n排序算法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (64, 6, 5, '堆和堆排序', '第堆和堆排序\n\n本章深入探讨堆和堆排序的核心概念与实践应用。堆和堆排序是软件工程中至关重要的主题。\n\n堆是一种完全二叉树结构。最大堆：父节点的值大于等于子节点；最小堆：父节点的值小于等于子节点。堆的基本操作：插入O(log n)、删除最大/最小O(log n)、建堆O(n)。堆排序：先建最大堆，然后反复取出堆顶元素，时间复杂度O(n log n)。优先队列是堆的典型应用。\n\n在实际开发中，堆和堆排序的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n堆和堆排序是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (65, 6, 6, '快速排序', '第快速排序\n\n本章深入探讨快速排序的核心概念与实践应用。快速排序是软件工程中至关重要的主题。\n\n快速排序选择基准元素，将数组分为小于基准和大于基准两部分，递归排序。平均时间复杂度O(n log n)，最坏O(n²)。随机化快速排序通过随机选择基准避免最坏情况。三数取中法也是常用优化。快速排序是实践中最快的通用排序算法。\n\n在实际开发中，快速排序的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n快速排序是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (66, 6, 7, '线性时间排序', '第线性时间排序\n\n本章深入探讨线性时间排序的核心概念与实践应用。线性时间排序是软件工程中至关重要的主题。\n\n非比较排序可以突破O(n log n)下界：计数排序O(n+k)适用于值域较小的整数；基数排序O(d(n+k))按位排序；桶排序平均O(n)将元素分配到有限数量的桶中。这些算法利用了数据的特殊性质。\n\n在实际开发中，线性时间排序的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n线性时间排序是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (67, 6, 8, '散列表', '第散列表\n\n本章深入探讨散列表的核心概念与实践应用。散列表是软件工程中至关重要的主题。\n\n散列表通过哈希函数直接定位元素，平均查找时间O(1)。哈希冲突处理：链地址法（每个桶维护一个链表）、开放地址法（线性探测、二次探测、双重散列）。好的哈希函数应均匀分布。负载因子影响性能，通常在0.75时扩容。Java的HashMap采用链地址法+红黑树优化。\n\n在实际开发中，散列表的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n散列表是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (68, 6, 9, '二叉搜索树', '第二叉搜索树\n\n本章深入探讨二叉搜索树的核心概念与实践应用。二叉搜索树是软件工程中至关重要的主题。\n\n二叉搜索树（BST）：左子树所有节点的值小于根节点，右子树所有节点的值大于根节点。基本操作：查找、插入、删除，时间复杂度O(h)，h为树高。中序遍历BST得到有序序列。最坏情况退化为链表，时间复杂度O(n)。\n\n在实际开发中，二叉搜索树的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n二叉搜索树是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (69, 6, 10, '红黑树', '第红黑树\n\n本章深入探讨红黑树的核心概念与实践应用。红黑树是软件工程中至关重要的主题。\n\n红黑树是一种自平衡二叉搜索树，保证最长路径不超过最短路径的两倍。五条性质：节点是红色或黑色、根节点是黑色、叶节点（NIL）是黑色、红节点的子节点是黑色、从任一节点到叶节点的路径上黑色节点数相同。插入和删除通过旋转和变色维持平衡。Java的TreeMap基于红黑树。\n\n在实际开发中，红黑树的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n红黑树是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (70, 6, 11, '动态规划', '第动态规划\n\n本章深入探讨动态规划的核心概念与实践应用。动态规划是软件工程中至关重要的主题。\n\n动态规划通过记忆化避免重复子问题计算。两个关键性质：最优子结构和重叠子问题。经典应用：最长公共子序列、背包问题、编辑距离、矩阵链乘法、最长递增子序列。自底向上（迭代）和自顶向下（递归+记忆化）两种实现方式。状态转移方程是动态规划的核心。\n\n在实际开发中，动态规划的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n动态规划是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (71, 6, 12, '贪心算法', '第贪心算法\n\n本章深入探讨贪心算法的核心概念与实践应用。贪心算法是软件工程中至关重要的主题。\n\n贪心算法每步做局部最优选择，期望得到全局最优解。贪心选择性质：局部最优选择能导致全局最优解。经典应用：活动选择问题、哈夫曼编码、最小生成树（Prim、Kruskal）、最短路径（Dijkstra）。贪心算法不一定能得到最优解，需要证明贪心选择性质。\n\n在实际开发中，贪心算法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n贪心算法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (72, 6, 13, '图算法基础', '第图算法基础\n\n本章深入探讨图算法基础的核心概念与实践应用。图算法基础是软件工程中至关重要的主题。\n\n图的表示：邻接矩阵和邻接表。图的遍历：广度优先搜索（BFS）和深度优先搜索（DFS）。最短路径：Dijkstra算法（单源、非负权）、Bellman-Ford算法（单源、允许负权）、Floyd-Warshall算法（全源）。最小生成树：Prim算法和Kruskal算法。拓扑排序用于有向无环图（DAG）。\n\n在实际开发中，图算法基础的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n图算法基础是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (73, 7, 1, '务实的哲学', '第务实的哲学\n\n本章深入探讨务实的哲学的核心概念与实践应用。务实的哲学是软件工程中至关重要的主题。\n\n本节深入讲解务实的哲学的核心知识。在现代软件工程实践中，务实的哲学扮演着不可或缺的角色。关注你的技艺，思考你的工作。不要容忍破窗户——看到糟糕的代码就修复它。做变化的催化剂。理论基础是实践的根基。\n\n在实际开发中，务实的哲学的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n务实的哲学是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (74, 7, 2, '务实的方法', '第务实的方法\n\n本章深入探讨务实的方法的核心概念与实践应用。务实的方法是软件工程中至关重要的主题。\n\n本节深入讲解务实的方法的核心知识。DRY原则（Don\'t Repeat Yourself）：每一块知识在系统中都只有一个明确的表示。正交性：消除不相关事物之间的影响。可撤销性：没有最终决策。曳光弹：快速构建端到端的骨架系统。原型与便笺：用原型学习。\n\n在实际开发中，务实的方法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n务实的方法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (75, 7, 3, '基本工具', '第基本工具\n\n本章深入探讨基本工具的核心概念与实践应用。基本工具是软件工程中至关重要的主题。\n\n本节深入讲解基本工具的核心知识。纯文本的力量：用纯文本保存知识。Shell游戏：熟练使用命令行。编辑器的力量：精通一种编辑器。版本控制：始终使用版本控制。调试：修复问题而不是指责。\n\n在实际开发中，基本工具的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n基本工具是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (76, 7, 4, '务实的偏执', '第务实的偏执\n\n本章深入探讨务实的偏执的核心概念与实践应用。务实的偏执是软件工程中至关重要的主题。\n\n本节深入讲解务实的偏执的核心知识。按合约设计（Design by Contract）：前置条件、后置条件、类不变式。死程序不说谎：尽早崩溃。断言式编程：用断言检查不可能的事情。如何平衡资源：始终以与分配相反的顺序释放资源。\n\n在实际开发中，务实的偏执的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n务实的偏执是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (77, 7, 5, '弯曲或折断', '第弯曲或折断\n\n本章深入探讨弯曲或折断的核心概念与实践应用。弯曲或折断是软件工程中至关重要的主题。\n\n本节深入讲解弯曲或折断的核心知识。解耦与得墨忒耳律：减少模块间的耦合。元编程：将抽象放进代码，细节放进元数据。时间耦合：分析工作流中的时间依赖。事件驱动和发布/订阅模式。\n\n在实际开发中，弯曲或折断的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n弯曲或折断是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (78, 7, 6, '当你编码时', '第当你编码时\n\n本章深入探讨当你编码时的核心概念与实践应用。当你编码时是软件工程中至关重要的主题。\n\n本节深入讲解当你编码时的核心知识。靠巧合编程：不要依赖巧合。算法速度：估算算法的阶。重构：早重构，常重构。易于测试的代码：为测试而设计。\n\n在实际开发中，当你编码时的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n当你编码时是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (79, 7, 7, '在项目开始之前', '第在项目开始之前\n\n本章深入探讨在项目开始之前的核心概念与实践应用。在项目开始之前是软件工程中至关重要的主题。\n\n本节深入讲解在项目开始之前的核心知识。需求之坑：不要搜集需求，要挖掘它们。解开不可能的谜题：面对约束条件时寻找创造性的解决方案。等你准备好：倾听内心的疑虑。\n\n在实际开发中，在项目开始之前的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n在项目开始之前是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (80, 7, 8, '务实的项目', '第务实的项目\n\n本章深入探讨务实的项目的核心概念与实践应用。务实的项目是软件工程中至关重要的主题。\n\n本节深入讲解务实的项目的核心知识。务实的团队：小而精的团队。无处不在的自动化：自动化一切可以自动化的事情。无情的测试：测试是代码的安全网。全都是写作：文档也是代码的一部分。\n\n在实际开发中，务实的项目的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n务实的项目是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (81, 7, 9, '注重实效的团队', '第注重实效的团队\n\n本章深入探讨注重实效的团队的核心概念与实践应用。注重实效的团队是软件工程中至关重要的主题。\n\n本节深入讲解注重实效的团队的核心知识。团队中的务实原则同样适用。不要容忍破窗户。保持团队的DRY。沟通是团队效率的关键。代码审查提升整体质量。\n\n在实际开发中，注重实效的团队的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n注重实效的团队是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (82, 7, 10, '够好即可的软件', '第够好即可的软件\n\n本章深入探讨够好即可的软件的核心概念与实践应用。够好即可的软件是软件工程中至关重要的主题。\n\n本节深入讲解够好即可的软件的核心知识。完美是优秀的敌人。让用户参与权衡。知道何时止步。适当的技术债务可以加速交付，但过度的技术债务会拖累整个项目。\n\n在实际开发中，够好即可的软件的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n够好即可的软件是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (83, 8, 1, '重构第一个示例', '第重构第一个示例\n\n本章深入探讨重构第一个示例的核心概念与实践应用。重构第一个示例是软件工程中至关重要的主题。\n\n整洁代码的核心理念：重构是在不改变外部行为的前提下改善代码内部结构。Martin Fowler通过一个视频租赁系统的示例，演示了如何逐步重构使代码变得更清晰。重构的第一步是确保有可靠的测试。\n\n在实际开发中，重构第一个示例的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n重构第一个示例是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (84, 8, 2, '重构原则', '第重构原则\n\n本章深入探讨重构原则的核心概念与实践应用。重构原则是软件工程中至关重要的主题。\n\n重构的定义：对软件内部结构的修改，在不改变其可观察行为的前提下，使其更易于理解和修改。何时重构：三次法则——事不过三，三则重构。重构与性能优化的区别。重构的时机：添加功能前、修复bug前、代码审查时。\n\n在实际开发中，重构原则的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n重构原则是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (85, 8, 3, '代码的坏味道', '第代码的坏味道\n\n本章深入探讨代码的坏味道的核心概念与实践应用。代码的坏味道是软件工程中至关重要的主题。\n\n常见代码坏味道：重复代码、过长函数、过大的类、过长参数列表、发散式变化、霰弹式修改、依恋情结、数据泥团、基本类型偏执、switch语句、平行继承体系、冗赘类、夸夸其谈的未来性、临时字段、过度耦合的消息链、中间人、不完美的库类。\n\n在实际开发中，代码的坏味道的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n代码的坏味道是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (86, 8, 4, '构筑测试体系', '第构筑测试体系\n\n本章深入探讨构筑测试体系的核心概念与实践应用。构筑测试体系是软件工程中至关重要的主题。\n\n整洁代码的核心理念：测试是重构的安全网。自测试代码的价值：每次编译后都运行测试。测试驱动开发（TDD）。测试夹具的使用。确保测试能检测到代码的行为变化。\n\n在实际开发中，构筑测试体系的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n构筑测试体系是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (87, 8, 5, '重构名录介绍', '第重构名录介绍\n\n本章深入探讨重构名录介绍的核心概念与实践应用。重构名录介绍是软件工程中至关重要的主题。\n\n重构名录的格式：名称、概要、动机、做法、范例。每种重构手法都有明确的步骤和适用场景。小步前进是重构的关键——每次只做一个小改动，然后测试。\n\n在实际开发中，重构名录介绍的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n重构名录介绍是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (88, 8, 6, '封装', '第封装\n\n本章深入探讨封装的核心概念与实践应用。封装是软件工程中至关重要的主题。\n\n封装相关的重构手法：封装变量（将公开变量变为私有，提供访问方法）、封装集合（不直接暴露集合，提供添加/删除方法）、以对象取代基本类型、以查询取代临时变量。封装是降低耦合的重要手段。\n\n在实际开发中，封装的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n封装是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (89, 8, 7, '搬移特性', '第搬移特性\n\n本章深入探讨搬移特性的核心概念与实践应用。搬移特性是软件工程中至关重要的主题。\n\n搬移相关的重构手法：搬移函数（将函数从一个类移到更合适的类）、搬移字段、搬移语句到函数、搬移语句到调用者、以函数调用取代内联代码、移动语句（调整代码顺序使相关代码靠近）、拆分循环、以管道取代循环。\n\n在实际开发中，搬移特性的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n搬移特性是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (90, 8, 8, '重新组织数据', '第重新组织数据\n\n本章深入探讨重新组织数据的核心概念与实践应用。重新组织数据是软件工程中至关重要的主题。\n\n数据组织相关的重构手法：拆分变量（一个变量不应承担多个职责）、字段改名、以查询取代派生变量、将引用对象改为值对象、将值对象改为引用对象。\n\n在实际开发中，重新组织数据的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n重新组织数据是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (91, 8, 9, '简化条件逻辑', '第简化条件逻辑\n\n本章深入探讨简化条件逻辑的核心概念与实践应用。简化条件逻辑是软件工程中至关重要的主题。\n\n条件逻辑相关的重构手法：分解条件表达式、合并条件表达式、以卫语句取代嵌套条件表达式、以多态取代条件表达式、引入特例（空对象模式）、引入断言。\n\n在实际开发中，简化条件逻辑的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n简化条件逻辑是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (92, 8, 10, '简化函数调用', '第简化函数调用\n\n本章深入探讨简化函数调用的核心概念与实践应用。简化函数调用是软件工程中至关重要的主题。\n\n函数调用相关的重构手法：函数改名、添加参数、移除参数、将查询函数和修改函数分离、以参数化方法取代重复方法、以明确函数取代参数、保持对象完整、以工厂函数取代构造函数。\n\n在实际开发中，简化函数调用的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n简化函数调用是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (93, 8, 11, '处理概括关系', '第处理概括关系\n\n本章深入探讨处理概括关系的核心概念与实践应用。处理概括关系是软件工程中至关重要的主题。\n\n概括关系（继承）相关的重构手法：字段上移、函数上移、构造函数本体上移、函数下移、字段下移、以子类取代类型码、移除子类、提炼超类、折叠继承体系、以委托取代子类、以委托取代超类。\n\n在实际开发中，处理概括关系的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n处理概括关系是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (94, 8, 12, '大型重构', '第大型重构\n\n本章深入探讨大型重构的核心概念与实践应用。大型重构是软件工程中至关重要的主题。\n\n大型重构需要团队协作和长期规划。梳理并分解继承体系、将过程化设计转化为对象设计、将领域逻辑与表述分离、提炼继承体系。大型重构的关键是小步前进，持续集成，保持系统始终可工作。\n\n在实际开发中，大型重构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n大型重构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (95, 9, 1, 'Redis入门', '第Redis入门\n\n本章深入探讨Redis入门的核心概念与实践应用。Redis入门是软件工程中至关重要的主题。\n\n数据库是信息系统的核心组件。Redis是一个开源的内存数据结构存储系统，可用作数据库、缓存和消息代理。Redis支持多种数据结构：字符串、哈希、列表、集合、有序集合。Redis的特点：速度快（内存操作）、支持持久化、支持事务、支持发布/订阅。\n\n在实际开发中，Redis入门的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nRedis入门是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (96, 9, 2, 'Redis数据结构', '第Redis数据结构\n\n本章深入探讨Redis数据结构的核心概念与实践应用。Redis数据结构是软件工程中至关重要的主题。\n\nRedis五种基本数据结构：STRING（字符串，最大512MB）、LIST（列表，双向链表）、SET（集合，无序不重复）、HASH（哈希，键值对集合）、ZSET（有序集合，带分数排序）。高级数据结构：HyperLogLog、Bitmap、Stream。\n\n在实际开发中，Redis数据结构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nRedis数据结构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (97, 9, 3, 'Redis命令', '第Redis命令\n\n本章深入探讨Redis命令的核心概念与实践应用。Redis命令是软件工程中至关重要的主题。\n\n常用命令：SET/GET（字符串）、LPUSH/RPUSH/LPOP/RPOP（列表）、SADD/SMEMBERS/SINTER（集合）、HSET/HGET/HGETALL（哈希）、ZADD/ZRANGE/ZRANGEBYSCORE（有序集合）。通用命令：DEL、EXISTS、EXPIRE、TTL、KEYS、TYPE。\n\n在实际开发中，Redis命令的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nRedis命令是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (98, 9, 4, '数据安全与性能保障', '第数据安全与性能保障\n\n本章深入探讨数据安全与性能保障的核心概念与实践应用。\n\nRedis持久化：RDB（快照，定时全量备份）和AOF（追加日志，记录每次写操作）。RDB优点是恢复速度快，AOF优点是数据更完整。混合持久化结合两者优点。Redis事务：MULTI/EXEC/DISCARD，不支持回滚。Redis的单线程模型保证了命令的原子性。\n\n在实际开发中，数据安全与性能保障的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n数据安全与性能保障是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (99, 9, 5, '使用Redis构建应用', '第使用Redis构建应用\n\n本章深入探讨使用Redis构建应用的核心概念与实践应用。\n\nRedis常见应用场景：缓存（减轻数据库压力）、会话管理（Session存储）、排行榜（有序集合ZSET）、计数器（INCR原子操作）、消息队列（LIST的LPUSH/BRPOP）、分布式锁（SETNX+EXPIRE）、限流（令牌桶/滑动窗口）。\n\n在实际开发中，使用Redis构建应用的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n使用Redis构建应用是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (100, 9, 6, '使用Redis构建支持程序', '第使用Redis构建支持程序\n\n本章深入探讨使用Redis构建支持程序的核心概念与实践应用。\n\n日志记录：使用LIST存储最近的日志。计数器与统计：使用HASH存储统计数据。服务发现：使用SET存储服务实例。配置管理：使用HASH存储配置项。\n\n在实际开发中，使用Redis构建支持程序的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n使用Redis构建支持程序是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (101, 9, 7, '基于搜索的应用', '第基于搜索的应用\n\n本章深入探讨基于搜索的应用的核心概念与实践应用。\n\n使用Redis实现搜索功能：倒排索引（SET存储词汇到文档的映射）、布尔搜索（SINTER/SUNION实现AND/OR）、排序搜索结果（SORT命令）。全文搜索的基本流程：分词、建立索引、查询、排序。\n\n在实际开发中，基于搜索的应用的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n基于搜索的应用是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (102, 9, 8, '社交网站', '第社交网站\n\n本章深入探讨社交网站的核心概念与实践应用。\n\n使用Redis构建社交功能：关注/粉丝关系（SET存储）、时间线（ZSET按时间排序）、状态更新（LIST推送）、共同关注（SINTER求交集）。Redis的高性能使其非常适合社交类应用的实时数据处理。\n\n在实际开发中，社交网站的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n社交网站是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (103, 9, 9, '降低内存占用', '第降低内存占用\n\n本章深入探讨降低内存占用的核心概念与实践应用。\n\nRedis内存优化：使用短键名、选择合适的数据结构（小数据量时用ziplist编码更省内存）、设置合理的过期时间、使用LRU/LFU淘汰策略。Redis内存回收机制：惰性删除和定期删除。maxmemory配置限制最大内存使用。\n\n在实际开发中，降低内存占用的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n降低内存占用是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (104, 9, 10, '扩展Redis', '第扩展Redis\n\n本章深入探讨扩展Redis的核心概念与实践应用。\n\nRedis扩展方案：主从复制（读写分离）、Redis Sentinel（高可用，自动故障转移）、Redis Cluster（分布式，数据分片）。Redis Cluster使用16384个哈希槽进行数据分片。一致性哈希与哈希槽的区别。\n\n在实际开发中，扩展Redis的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n扩展Redis是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (105, 9, 11, 'Redis的Lua脚本', '第Redis的Lua脚本\n\n本章深入探讨Redis的Lua脚本的核心概念与实践应用。\n\nRedis支持使用Lua脚本执行复杂操作。EVAL命令执行Lua脚本，脚本中的所有操作是原子的。EVALSHA使用脚本的SHA1摘要执行缓存的脚本。Lua脚本可以访问KEYS和ARGV参数。适用于需要原子性的多步操作。\n\n在实际开发中，Redis的Lua脚本的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nRedis的Lua脚本是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (106, 10, 1, 'MySQL架构与历史', '第MySQL架构与历史\n\n本章深入探讨MySQL架构与历史的核心概念与实践应用。\n\nMySQL的逻辑架构分为三层：连接层（处理客户端连接）、服务层（查询解析、优化、缓存）、存储引擎层（InnoDB、MyISAM等）。InnoDB是MySQL默认存储引擎，支持事务、行级锁、外键。MyISAM不支持事务但查询速度快。\n\n在实际开发中，MySQL架构与历史的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nMySQL架构与历史是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (107, 10, 2, 'MySQL基准测试', '第MySQL基准测试\n\n本章深入探讨MySQL基准测试的核心概念与实践应用。\n\n基准测试用于衡量数据库性能。常用工具：sysbench、mysqlslap。关键指标：QPS（每秒查询数）、TPS（每秒事务数）、响应时间、并发连接数。测试要点：模拟真实负载、控制变量、多次测试取平均值。\n\n在实际开发中，MySQL基准测试的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nMySQL基准测试是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (108, 10, 3, '服务器性能剖析', '第服务器性能剖析\n\n本章深入探讨服务器性能剖析的核心概念与实践应用。\n\n性能剖析工具：SHOW PROFILE、Performance Schema、慢查询日志。性能瓶颈分析：CPU瓶颈、IO瓶颈、网络瓶颈、锁争用。优化策略：减少不必要的查询、优化慢查询、合理使用缓存。\n\n在实际开发中，服务器性能剖析的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n服务器性能剖析是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (109, 10, 4, 'Schema与数据类型优化', '第Schema与数据类型优化\n\n本章深入探讨Schema与数据类型优化的核心概念与实践应用。\n\n数据类型选择原则：更小的通常更好、简单就好、尽量避免NULL。整数类型：TINYINT/SMALLINT/INT/BIGINT。字符串类型：CHAR（定长）vs VARCHAR（变长）。日期时间：DATETIME vs TIMESTAMP。Schema设计范式：第一范式（原子性）、第二范式（完全依赖）、第三范式（消除传递依赖）。适当的反范式化可以提升查询性能。\n\n在实际开发中，Schema与数据类型优化的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nSchema与数据类型优化是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (110, 10, 5, '创建高性能索引', '第创建高性能索引\n\n本章深入探讨创建高性能索引的核心概念与实践应用。\n\nB+树索引是最常用的索引类型。创建索引的原则：在WHERE、JOIN、ORDER BY涉及的列上建索引；遵循最左前缀原则；避免在低选择性列上建索引；覆盖索引可以减少回表操作。EXPLAIN命令用于分析查询执行计划。索引失效场景：函数操作、隐式类型转换、LIKE以通配符开头、OR条件。\n\n在实际开发中，创建高性能索引的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n创建高性能索引是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (111, 10, 6, '查询性能优化', '第查询性能优化\n\n本章深入探讨查询性能优化的核心概念与实践应用。\n\n查询优化基本步骤：使用EXPLAIN分析执行计划、检查是否使用了索引、减少扫描行数。优化技巧：避免SELECT *、使用LIMIT分页、优化JOIN（小表驱动大表）、避免子查询（用JOIN代替）、使用UNION ALL替代UNION。慢查询日志帮助发现性能问题。\n\n在实际开发中，查询性能优化的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n查询性能优化是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (112, 10, 7, 'MySQL高级特性', '第MySQL高级特性\n\n本章深入探讨MySQL高级特性的核心概念与实践应用。\n\n分区表：按范围、列表、哈希、键分区。视图：虚拟表，简化复杂查询。存储过程：预编译的SQL程序。触发器：自动响应INSERT/UPDATE/DELETE。事件调度器：定时执行任务。全文索引：FULLTEXT类型，支持自然语言搜索。\n\n在实际开发中，MySQL高级特性的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nMySQL高级特性是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (113, 10, 8, '优化服务器设置', '第优化服务器设置\n\n本章深入探讨优化服务器设置的核心概念与实践应用。\n\n关键配置参数：innodb_buffer_pool_size（InnoDB缓冲池大小，建议为可用内存的70-80%）、max_connections（最大连接数）、query_cache_size（查询缓存，MySQL 8.0已移除）、innodb_log_file_size（redo日志大小）。\n\n在实际开发中，优化服务器设置的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n优化服务器设置是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (114, 10, 9, '操作系统和硬件优化', '第操作系统和硬件优化\n\n本章深入探讨操作系统和硬件优化的核心概念与实践应用。\n\n硬件选择：SSD vs HDD（SSD对随机IO提升巨大）、内存大小（越大越能缓存数据）、CPU（多核对并发有利）。操作系统优化：文件系统选择（XFS/EXT4）、IO调度算法、swap配置、网络参数优化。\n\n在实际开发中，操作系统和硬件优化的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n操作系统和硬件优化是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (115, 10, 10, '复制', '第复制\n\n本章深入探讨复制的核心概念与实践应用。\n\nMySQL复制原理：主库将变更写入binlog，从库的IO线程读取binlog写入relay log，SQL线程重放relay log。复制模式：异步复制、半同步复制、组复制（Group Replication）。复制拓扑：一主一从、一主多从、级联复制、双主复制。\n\n在实际开发中，复制的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n复制是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (116, 10, 11, '可扩展的MySQL', '第可扩展的MySQL\n\n本章深入探讨可扩展的MySQL的核心概念与实践应用。\n\n扩展策略：垂直扩展（升级硬件）、水平扩展（分库分表）。分库分表策略：按范围分片、按哈希分片。分片中间件：ShardingSphere、MyCat。读写分离：主库写、从库读。数据一致性问题与解决方案。\n\n在实际开发中，可扩展的MySQL的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n可扩展的MySQL是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (117, 10, 12, '高可用性', '第高可用性\n\n本章深入探讨高可用性的核心概念与实践应用。\n\n高可用方案：MySQL Replication + MHA（自动故障转移）、MySQL InnoDB Cluster（基于组复制）、Galera Cluster（同步多主复制）。故障检测与自动切换。数据备份策略：mysqldump逻辑备份、xtrabackup物理备份、binlog增量备份。RPO和RTO指标。\n\n在实际开发中，高可用性的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n高可用性是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (118, 11, 1, '引言', '第引言\n\n本章深入探讨引言的核心概念与实践应用。引言是数据库系统的入门主题。\n\n数据库系统的目的是管理大量数据。数据库管理系统（DBMS）提供数据定义、数据操纵、数据控制功能。数据模型：层次模型、网状模型、关系模型、对象关系模型。数据库系统的三级模式结构：外模式、概念模式、内模式。\n\n在实际开发中，引言的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n引言是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (119, 11, 2, '关系模型介绍', '第关系模型介绍\n\n本章深入探讨关系模型介绍的核心概念与实践应用。\n\n关系模型由E.F.Codd于1970年提出。核心概念：关系（表）、元组（行）、属性（列）、域、码（键）。超码、候选码、主码、外码的区别。关系代数：选择σ、投影π、并∪、差-、笛卡尔积×、自然连接⋈。\n\n在实际开发中，关系模型介绍的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n关系模型介绍是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (120, 11, 3, 'SQL基础', '第SQL基础\n\n本章深入探讨SQL基础的核心概念与实践应用。\n\nSQL语言分为：DDL（CREATE/ALTER/DROP）、DML（SELECT/INSERT/UPDATE/DELETE）、DCL（GRANT/REVOKE）。SELECT语句：FROM、WHERE、GROUP BY、HAVING、ORDER BY、LIMIT。聚合函数：COUNT、SUM、AVG、MAX、MIN。连接查询：内连接、左外连接、右外连接、全外连接。\n\n在实际开发中，SQL基础的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nSQL基础是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (121, 11, 4, '中级SQL', '第中级SQL\n\n本章深入探讨中级SQL的核心概念与实践应用。\n\n子查询：标量子查询、行子查询、表子查询。EXISTS和NOT EXISTS。WITH子句（CTE，公共表表达式）。窗口函数：ROW_NUMBER、RANK、DENSE_RANK、LAG、LEAD、SUM OVER。视图的创建和使用。\n\n在实际开发中，中级SQL的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n中级SQL是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (122, 11, 5, '高级SQL', '第高级SQL\n\n本章深入探讨高级SQL的核心概念与实践应用。\n\n触发器：BEFORE/AFTER INSERT/UPDATE/DELETE。存储过程和函数。游标的使用。动态SQL。递归查询。JSON数据类型和操作。\n\n在实际开发中，高级SQL的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n高级SQL是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (123, 11, 6, '数据库设计与E-R模型', '第数据库设计与E-R模型\n\n本章深入探讨数据库设计与E-R模型的核心概念与实践应用。\n\nE-R模型（实体-关系模型）用于数据库概念设计。实体、属性、关系。关系的类型：一对一、一对多、多对多。E-R图的绘制。从E-R图到关系模式的转换规则。\n\n在实际开发中，数据库设计与E-R模型的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n数据库设计与E-R模型是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (124, 11, 7, '关系数据库设计', '第关系数据库设计\n\n本章深入探讨关系数据库设计的核心概念与实践应用。\n\n函数依赖：X→Y表示X的值决定Y的值。范式化理论：1NF（原子性）、2NF（消除部分依赖）、3NF（消除传递依赖）、BCNF（每个决定因素都是候选码）。Armstrong公理：自反性、增广性、传递性。分解的无损连接性和依赖保持性。\n\n在实际开发中，关系数据库设计的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n关系数据库设计是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (125, 11, 8, '存储和文件结构', '第存储和文件结构\n\n本章深入探讨存储和文件结构的核心概念与实践应用。\n\n存储介质层次：高速缓存、主存、闪存、磁盘、磁带。文件组织方式：堆文件、顺序文件、散列文件。记录的定长和变长存储。缓冲区管理。\n\n在实际开发中，存储和文件结构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n存储和文件结构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (126, 11, 9, '索引', '第索引\n\n本章深入探讨索引的核心概念与实践应用。\n\n索引类型：顺序索引（稠密/稀疏）、B+树索引、散列索引、位图索引。B+树：所有数据在叶子节点，叶子节点通过指针连接。B+树的插入和删除操作。多级索引。聚集索引vs非聚集索引。\n\n在实际开发中，索引的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n索引是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (127, 11, 10, '查询处理', '第查询处理\n\n本章深入探讨查询处理的核心概念与实践应用。\n\n查询处理步骤：解析→优化→执行。选择操作的实现：全表扫描、索引扫描。连接操作的实现：嵌套循环连接、排序合并连接、散列连接。排序的实现：内排序、外排序。代价模型：IO代价+CPU代价。\n\n在实际开发中，查询处理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n查询处理是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (128, 11, 11, '查询优化', '第查询优化\n\n本章深入探讨查询优化的核心概念与实践应用。\n\n查询优化策略：等价变换规则（选择下推、投影下推、连接顺序优化）。基于代价的优化：统计信息、代价估算。启发式优化规则。物化视图与查询重写。\n\n在实际开发中，查询优化的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n查询优化是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (129, 11, 12, '事务', '第事务\n\n本章深入探讨事务的核心概念与实践应用。\n\n事务的ACID特性：原子性(Atomicity)、一致性(Consistency)、隔离性(Isolation)、持久性(Durability)。事务状态：活动→部分提交→提交/失败→中止。事务隔离级别：读未提交、读已提交、可重复读、可串行化。并发问题：脏读、不可重复读、幻读。\n\n在实际开发中，事务的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n事务是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (130, 11, 13, '并发控制', '第并发控制\n\n本章深入探讨并发控制的核心概念与实践应用。\n\n锁机制：共享锁（S锁，读锁）、排他锁（X锁，写锁）。两阶段锁协议（2PL）：增长阶段获取锁，缩减阶段释放锁。死锁处理：死锁预防、死锁检测（等待图）、超时机制。MVCC（多版本并发控制）：通过保存数据的多个版本实现非阻塞读。InnoDB的MVCC实现：undo log、ReadView。\n\n在实际开发中，并发控制的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n并发控制是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (131, 12, 1, '精华', '第精华\n\n本章深入探讨精华的核心概念与实践应用。精华是软件工程中至关重要的主题。\n\nJavaScript是一门动态类型、基于原型的多范式语言。JavaScript有好的部分也有糟粕。本书的目标是帮助读者发掘JavaScript的精华部分，避免糟粕。JavaScript的核心优势：函数是一等公民、动态对象、松散的类型系统。\n\n在实际开发中，精华的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n精华是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (132, 12, 2, '语法', '第语法\n\n本章深入探讨语法的核心概念与实践应用。语法是软件工程中至关重要的主题。\n\n本节深入讲解语法的核心知识。JavaScript的语法：变量声明（var/let/const）、数据类型（number, string, boolean, null, undefined, object, symbol）、运算符、控制流（if/else, for, while, switch）。类型转换和==vs===的区别。\n\n在实际开发中，语法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n语法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (133, 12, 3, '对象', '第对象\n\n本章深入探讨对象的核心概念与实践应用。对象是软件工程中至关重要的主题。\n\nJavaScript中几乎一切都是对象。对象字面量创建：{}。属性访问：点号和方括号。对象是键值对的集合。原型链：每个对象都有一个原型。Object.create()创建以指定对象为原型的新对象。\n\n在实际开发中，对象的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n对象是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (134, 12, 4, '函数', '第函数\n\n本章深入探讨函数的核心概念与实践应用。函数是JavaScript中最重要的部分。\n\n函数是代码组织的基本单元。JavaScript中函数是一等公民，可以赋值给变量、作为参数传递、作为返回值。函数调用的四种模式：方法调用、函数调用、构造器调用、apply/call调用。闭包：函数能够访问其定义时的词法环境中的变量。柯里化和高阶函数。\n\n在实际开发中，函数的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n函数是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (135, 12, 5, '继承', '第继承\n\n本章深入探讨继承的核心概念与实践应用。继承是软件工程中至关重要的主题。\n\nJavaScript的继承基于原型而非类。原型继承：对象直接从其他对象继承。伪类模式：使用构造函数+new关键字模拟类继承。函数式继承：使用闭包实现私有变量和方法。ES6的class语法是原型继承的语法糖。\n\n在实际开发中，继承的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n继承是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (136, 12, 6, '数组', '第数组\n\n本章深入探讨数组的核心概念与实践应用。数组是软件工程中至关重要的主题。\n\nJavaScript的数组实际上是对象。数组字面量：[]。数组方法：push、pop、shift、unshift、splice、slice、concat、join、map、filter、reduce、forEach、find、some、every。数组和对象的区别：数组有length属性和数字索引。\n\n在实际开发中，数组的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n数组是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (137, 12, 7, '正则表达式', '第正则表达式\n\n本章深入探讨正则表达式的核心概念与实践应用。正则表达式是软件工程中至关重要的主题。\n\n正则表达式用于模式匹配。元字符：. ^ $ * + ? {} [] () | \\。字符类：\\d数字、\\w单词字符、\\s空白。量词：*零次或多次、+一次或多次、?零次或一次。正则方法：test、exec、match、replace、search、split。\n\n在实际开发中，正则表达式的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n正则表达式是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (138, 12, 8, '方法', '第方法\n\n本章深入探讨方法的核心概念与实践应用。方法是JavaScript内置类型的核心功能。\n\n常用方法：Array（concat, join, pop, push, reverse, shift, slice, sort, splice, unshift）、String（charAt, indexOf, match, replace, search, slice, split, toLowerCase, toUpperCase）、Number（toFixed, toString）。\n\n在实际开发中，方法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n方法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (139, 12, 9, '代码风格', '第代码风格\n\n本章深入探讨代码风格的核心概念与实践应用。代码风格是软件工程中至关重要的主题。\n\n整洁代码的核心理念：一致的代码风格提高可读性。使用ESLint/Prettier自动化代码格式化。缩进、命名约定、分号使用。避免全局变量。使用严格模式（\'use strict\'）。\n\n在实际开发中，代码风格的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n代码风格是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (140, 12, 10, '优美的特性', '第优美的特性\n\n本章深入探讨优美的特性的核心概念与实践应用。优美的特性是JavaScript中值得学习的部分。\n\nJavaScript的优美特性：函数字面量、动态对象、松散类型（灵活但需谨慎）、对象字面量、原型继承。这些特性使JavaScript成为一门非常灵活和强大的语言。\n\n在实际开发中，优美的特性的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n优美的特性是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (141, 12, 11, '糟粕', '第糟粕\n\n本章深入探讨糟粕的核心概念与实践应用。糟粕是JavaScript中应该避免的部分。\n\n应避免的特性：全局变量、with语句、eval函数、==（使用===代替）、typeof null返回\"object\"。容易出错的部分：自动分号插入、浮点数精度问题（0.1+0.2!==0.3）、arguments对象的陷阱。\n\n在实际开发中，了解糟粕有助于避免踩坑。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n糟粕是软件开发中需要注意的知识领域。');
INSERT INTO `book_content` VALUES (142, 12, 12, '毒瘤', '第毒瘤\n\n本章深入探讨毒瘤的核心概念与实践应用。毒瘤是JavaScript中最危险的部分。\n\n最应避免的特性：全局变量污染（使用模块化解决）、类型转换的怪癖、void运算符、位运算符（JavaScript中数字是浮点数）、function语句vs function表达式。现代JavaScript（ES6+）已经解决了很多历史问题。\n\n在实际开发中，了解毒瘤有助于写出更安全的代码。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n毒瘤是软件开发中需要警惕的知识领域。');
INSERT INTO `book_content` VALUES (143, 13, 1, '作用域与闭包', '第作用域与闭包\n\n本章深入探讨作用域与闭包的核心概念与实践应用。\n\nJavaScript是一门动态类型、基于原型的多范式语言。作用域决定了变量的可访问性，JavaScript有全局作用域、函数作用域和块作用域（let/const）。闭包是JavaScript的核心特性：函数能够访问其定义时的词法环境中的变量，即使该函数在其原始作用域之外被调用。闭包常用于数据私有化、模块模式和函数工厂。\n\n在实际开发中，作用域与闭包的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n作用域与闭包是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (144, 13, 2, 'this与对象原型', '第this与对象原型\n\n本章深入探讨this与对象原型的核心概念与实践应用。\n\nthis关键字：this的值取决于函数的调用方式。默认绑定（全局对象/undefined）、隐式绑定（调用对象）、显式绑定（call/apply/bind）、new绑定。箭头函数没有自己的this，继承外层的this。原型链：JavaScript的继承基于原型。每个对象都有一个内部链接指向其原型对象。ES6的class语法是原型继承的语法糖。\n\n在实际开发中，this与对象原型的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nthis与对象原型是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (145, 13, 3, '类型与语法', '第类型与语法\n\n本章深入探讨类型与语法的核心概念与实践应用。\n\nJavaScript的七种内置类型：string、number、boolean、null、undefined、object、symbol。typeof运算符的特殊行为：typeof null === \"object\"。值类型vs引用类型。类型转换：显式转换和隐式转换。== vs ===：==允许类型转换，===不允许。\n\n在实际开发中，类型与语法的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n类型与语法是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (146, 13, 4, '异步与性能', '第异步与性能\n\n本章深入探讨异步与性能的核心概念与实践应用。\n\n异步编程：回调函数是最基本的异步处理方式，但容易导致回调地狱。Promise提供了链式调用的解决方案。async/await是Promise的语法糖，使异步代码看起来像同步代码。事件循环（Event Loop）是JavaScript异步模型的核心，宏任务（setTimeout）和微任务（Promise.then）有不同的优先级。\n\n在实际开发中，异步与性能的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n异步与性能是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (147, 13, 5, 'ES6与未来', '第ES6与未来\n\n本章深入探讨ES6与未来的核心概念与实践应用。\n\nES6（ES2015）重要特性：let/const块作用域、箭头函数、模板字符串、解构赋值、默认参数、展开运算符、Symbol、Promise、class语法、模块系统（import/export）、Iterator和Generator、Map/Set、Proxy/Reflect。后续版本：async/await（ES2017）、可选链?.（ES2020）、空值合并??（ES2020）。\n\n在实际开发中，ES6与未来的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nES6与未来是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (148, 13, 6, '作用域是什么', '第作用域是什么\n\n本章深入探讨作用域是什么的核心概念与实践应用。\n\n作用域是一组规则，用于确定在何处以及如何查找变量。编译原理基础：词法分析、语法分析、代码生成。LHS查询（赋值目标）和RHS查询（赋值源）。引擎、编译器和作用域的协作。ReferenceError（变量未找到）和TypeError（对找到的变量执行非法操作）。\n\n在实际开发中，作用域是什么的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n作用域是什么是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (149, 13, 7, '词法作用域', '第词法作用域\n\n本章深入探讨词法作用域的核心概念与实践应用。\n\n词法作用域在写代码时就确定了（静态作用域）。作用域查找从最内层开始，逐层向外查找直到找到第一个匹配。eval()和with可以动态修改词法作用域（不推荐使用）。遮蔽效应：内层作用域中的同名变量会遮蔽外层的。\n\n在实际开发中，词法作用域的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n词法作用域是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (150, 13, 8, '函数作用域与块作用域', '第函数作用域与块作用域\n\n本章深入探讨函数作用域与块作用域的核心概念与实践应用。\n\n函数作用域：函数内部声明的变量在外部不可访问。IIFE（立即执行函数表达式）创建独立作用域。块作用域：ES6的let和const在{}内创建块作用域。let没有变量提升（暂时性死区TDZ）。const声明的变量不能重新赋值（但对象的属性可以修改）。\n\n在实际开发中，函数作用域与块作用域的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n函数作用域与块作用域是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (151, 13, 9, '提升', '第提升\n\n本章深入探讨提升的核心概念与实践应用。\n\n变量提升：var声明的变量会被提升到函数作用域顶部，但赋值不会。函数声明会整体提升，函数表达式不会。let和const不存在提升（存在暂时性死区）。同名时函数声明优先于变量声明。\n\n在实际开发中，提升的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n提升是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (152, 13, 10, '闭包', '第闭包\n\n本章深入探讨闭包的核心概念与实践应用。\n\n闭包是JavaScript的核心特性。当函数可以记住并访问所在的词法作用域时，就产生了闭包，即使函数在当前词法作用域之外执行。经典应用：模块模式、函数工厂、柯里化、循环中的闭包（for循环+setTimeout的经典面试题，用let或IIFE解决）。闭包的注意事项：可能导致内存泄漏。\n\n在实际开发中，闭包的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n闭包是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (153, 13, 11, 'this全面解析', '第this全面解析\n\n本章深入探讨this全面解析的核心概念与实践应用。\n\nthis绑定的四条规则（优先级从低到高）：1.默认绑定（独立函数调用，this指向全局对象/undefined）。2.隐式绑定（方法调用，this指向调用对象）。3.显式绑定（call/apply/bind）。4.new绑定（构造函数调用）。箭头函数的this继承外层。this的常见陷阱：回调函数中this丢失、方法赋值给变量后this丢失。\n\n在实际开发中，this全面解析的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nthis全面解析是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (154, 14, 1, '引言', '第引言\n\n本章深入探讨引言的核心概念与实践应用。\n\nCSS（层叠样式表）控制网页的视觉表现。现代CSS已经发展为一门强大的设计语言。盒模型是CSS布局的基础：每个元素都是一个矩形盒子，由content、padding、border和margin组成。box-sizing: border-box使width和height包含padding和border。\n\n在实际开发中，引言的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n引言是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (155, 14, 2, '背景与边框', '第背景与边框\n\n本章深入探讨背景与边框的核心概念与实践应用。\n\nCSS背景属性：background-color、background-image、background-repeat、background-position、background-size。多重背景：可以叠加多个背景图。background-clip控制背景的绘制区域。边框：border-radius圆角、border-image边框图片、box-shadow阴影。\n\n在实际开发中，背景与边框的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n背景与边框是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (156, 14, 3, '形状', '第形状\n\n本章深入探讨形状的核心概念与实践应用。\n\nCSS创建形状：圆形（border-radius: 50%）、椭圆（border-radius的不同水平/垂直值）、三角形（利用border的特性）、平行四边形（transform: skew）、菱形（clip-path或transform: rotate）。clip-path属性可以创建任意形状的裁剪区域。shape-outside实现文字环绕非矩形区域。\n\n在实际开发中，形状的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n形状是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (157, 14, 4, '视觉效果', '第视觉效果\n\n本章深入探讨视觉效果的核心概念与实践应用。\n\nCSS视觉效果：box-shadow（单侧投影、双侧投影、不规则投影）、text-shadow文字阴影、filter滤镜（blur模糊、brightness亮度、contrast对比度、grayscale灰度、sepia复古）、mix-blend-mode混合模式、opacity透明度。backdrop-filter实现毛玻璃效果。\n\n在实际开发中，视觉效果的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n视觉效果是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (158, 14, 5, '字体排印', '第字体排印\n\n本章深入探讨字体排印的核心概念与实践应用。\n\nCSS字体排印：@font-face引入自定义字体。font-family字体栈。font-size、line-height、letter-spacing、word-spacing。text-align文本对齐。text-overflow: ellipsis文本溢出省略。CSS Hyphens自动断字。多列布局column-count/column-width。\n\n在实际开发中，字体排印的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n字体排印是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (159, 14, 6, '用户体验', '第用户体验\n\n本章深入探讨用户体验的核心概念与实践应用。\n\n提升用户体验的CSS技巧：自定义复选框/单选框、扩大可点击区域（padding或伪元素）、自定义滚动条（::-webkit-scrollbar）、平滑滚动（scroll-behavior: smooth）、交互反馈（:hover、:active、:focus状态）。\n\n在实际开发中，用户体验的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n用户体验是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (160, 14, 7, '结构与布局', '第结构与布局\n\n本章深入探讨结构与布局的核心概念与实践应用。\n\nFlexbox弹性布局：display: flex创建弹性容器。justify-content控制主轴对齐。align-items控制交叉轴对齐。Grid网格布局：display: grid创建网格容器。grid-template-columns/rows定义网格轨道。gap设置间距。fr单位按比例分配空间。居中技巧：margin: auto、flex居中、grid居中、transform居中。\n\n在实际开发中，结构与布局的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n结构与布局是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (161, 14, 8, '过渡与动画', '第过渡与动画\n\n本章深入探讨过渡与动画的核心概念与实践应用。\n\ntransition实现简单过渡效果：transition-property、transition-duration、transition-timing-function、transition-delay。@keyframes定义复杂动画序列。animation属性：animation-name、animation-duration、animation-iteration-count、animation-direction。transform实现2D/3D变换：translate、rotate、scale、skew。\n\n在实际开发中，过渡与动画的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n过渡与动画是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (162, 14, 9, '半透明边框', '第半透明边框\n\n本章深入探讨半透明边框的核心概念与实践应用。\n\n使用rgba()或hsla()设置半透明颜色。background-clip: padding-box使背景不延伸到边框区域，从而实现半透明边框效果。CSS变量（自定义属性）：--color-primary: #409EFF; 使用时 color: var(--color-primary)。\n\n在实际开发中，半透明边框的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n半透明边框是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (163, 14, 10, '多重边框', '第多重边框\n\n本章深入探讨多重边框的核心概念与实践应用。\n\n实现多重边框的方法：box-shadow（利用扩展半径模拟多重边框，不影响布局）、outline（outline-offset可以为负值实现内边框）。box-shadow可以叠加多层，实现任意数量的\"边框\"效果。\n\n在实际开发中，多重边框的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n多重边框是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (164, 14, 11, '灵活的背景定位', '第灵活的背景定位\n\n本章深入探讨灵活的背景定位的核心概念与实践应用。\n\nbackground-position的扩展语法可以指定相对于任意角的偏移。background-origin改变定位的参考框（padding-box/content-box/border-box）。calc()函数实现精确计算定位。\n\n在实际开发中，灵活的背景定位的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n灵活的背景定位是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (165, 14, 12, '条纹背景', '第条纹背景\n\n本章深入探讨条纹背景的核心概念与实践应用。\n\n使用CSS渐变实现条纹背景：linear-gradient配合background-size。水平条纹、垂直条纹、斜向条纹（repeating-linear-gradient）。通过调整色标位置控制条纹宽度。渐变可以叠加实现复杂图案。\n\n在实际开发中，条纹背景的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n条纹背景是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (166, 15, 1, '计算机网络和因特网', '第计算机网络和因特网\n\n本章深入探讨计算机网络和因特网的核心概念与实践应用。\n\n计算机网络采用分层架构。TCP/IP四层模型：应用层（HTTP、FTP、DNS、SMTP）、传输层（TCP、UDP）、网络层（IP、ICMP、ARP）、数据链路层（以太网、WiFi）。分组交换vs电路交换。协议分层的优点：模块化设计，各层独立演化。\n\n在实际开发中，计算机网络和因特网的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n计算机网络和因特网是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (167, 15, 2, '应用层', '第应用层\n\n本章深入探讨应用层的核心概念与实践应用。\n\nHTTP协议是Web的基础。HTTP/1.1引入持久连接。HTTP/2：二进制帧层、多路复用、头部压缩、服务器推送。HTTP/3基于QUIC协议（UDP）。DNS域名系统将域名解析为IP地址。SMTP/POP3/IMAP用于电子邮件。FTP文件传输协议。P2P架构。\n\n在实际开发中，应用层的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n应用层是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (168, 15, 3, '运输层', '第运输层\n\n本章深入探讨运输层的核心概念与实践应用。\n\nTCP协议提供可靠的面向连接的字节流服务。三次握手建立连接：SYN→SYN+ACK→ACK。四次挥手断开连接：FIN→ACK→FIN→ACK。TCP的可靠性通过序列号、确认应答、超时重传实现。流量控制使用滑动窗口机制。拥塞控制：慢启动、拥塞避免、快重传、快恢复。UDP是无连接的不可靠传输协议，开销小速度快。\n\n在实际开发中，运输层的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n运输层是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (169, 15, 4, '网络层数据平面', '第网络层数据平面\n\n本章深入探讨网络层数据平面的核心概念与实践应用。\n\n网络层负责将数据包从源主机传送到目的主机。IP协议：IPv4地址（32位，点分十进制）、子网掩码、CIDR无类域间路由。IPv6地址（128位）。NAT网络地址转换。DHCP动态主机配置协议。路由器的转发表和转发功能。\n\n在实际开发中，网络层数据平面的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n网络层数据平面是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (170, 15, 5, '网络层控制平面', '第网络层控制平面\n\n本章深入探讨网络层控制平面的核心概念与实践应用。\n\n路由算法：链路状态算法（Dijkstra，如OSPF）、距离向量算法（Bellman-Ford，如RIP）。自治系统间路由：BGP（边界网关协议）。SDN（软件定义网络）：控制平面与数据平面分离。ICMP协议用于网络诊断（ping、traceroute）。\n\n在实际开发中，网络层控制平面的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n网络层控制平面是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (171, 15, 6, '链路层和局域网', '第链路层和局域网\n\n本章深入探讨链路层和局域网的核心概念与实践应用。\n\n链路层负责相邻节点间的数据传输。以太网是最流行的局域网技术。MAC地址（48位）。ARP协议将IP地址映射为MAC地址。交换机工作在链路层，根据MAC地址转发帧。CSMA/CD冲突检测。VLAN虚拟局域网。\n\n在实际开发中，链路层和局域网的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n链路层和局域网是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (172, 15, 7, '无线网络和移动网络', '第无线网络和移动网络\n\n本章深入探讨无线网络和移动网络的核心概念与实践应用。\n\nWiFi（802.11）：2.4GHz和5GHz频段。CSMA/CA冲突避免。蜂窝网络：2G/3G/4G/5G。移动IP：允许移动设备保持IP不变。无线网络的特殊问题：信号衰减、多径效应、隐藏终端问题。\n\n在实际开发中，无线网络和移动网络的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n无线网络和移动网络是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (173, 15, 8, '计算机网络中的安全', '第计算机网络中的安全\n\n本章深入探讨计算机网络中的安全的核心概念与实践应用。\n\n网络安全是信息时代的核心挑战。密码学基础：对称加密（AES）、非对称加密（RSA）。数字签名和数字证书。TLS/SSL协议保护传输安全。防火墙和入侵检测系统。常见攻击：DoS/DDoS、中间人攻击、DNS劫持。\n\n在实际开发中，计算机网络中的安全的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n计算机网络中的安全是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (174, 15, 9, '多媒体网络', '第多媒体网络\n\n本章深入探讨多媒体网络的核心概念与实践应用。\n\n流媒体传输：HTTP流式传输、DASH（基于HTTP的动态自适应流）。RTP实时传输协议。VoIP网络电话。内容分发网络（CDN）：通过DNS智能解析将用户请求导向最近的节点。QoS服务质量保障。\n\n在实际开发中，多媒体网络的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n多媒体网络是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (175, 15, 10, '网络管理', '第网络管理\n\n本章深入探讨网络管理的核心概念与实践应用。\n\nSNMP（简单网络管理协议）用于网络设备监控和管理。MIB管理信息库。网络监控工具：Nagios、Zabbix、Prometheus。网络配置管理。故障管理和性能管理。网络自动化和NetDevOps。\n\n在实际开发中，网络管理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n网络管理是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (176, 16, 1, '概述', '第概述\n\n本章深入探讨概述的核心概念与实践应用。\n\nTCP/IP协议族是Internet的基础。分层模型：链路层、网络层、传输层、应用层。每一层的协议为上层提供服务，对上层隐藏细节。封装：数据在发送端逐层添加头部，在接收端逐层剥离头部。\n\n在实际开发中，概述的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n概述是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (177, 16, 2, '链路层', '第链路层\n\n本章深入探讨链路层的核心概念与实践应用。\n\n链路层负责在相邻节点间传输帧。以太网帧格式：目的MAC、源MAC、类型、数据、FCS校验。MTU（最大传输单元）：以太网默认1500字节。环回接口（127.0.0.1）。串行线路和PPP协议。\n\n在实际开发中，链路层的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n链路层是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (178, 16, 3, 'IP协议', '第IP协议\n\n本章深入探讨IP协议的核心概念与实践应用。\n\nIP协议是网络层的核心协议，提供不可靠、无连接的数据报传输服务。IPv4头部：版本、首部长度、总长度、标识、标志、偏移、TTL、协议、校验和、源IP、目的IP。IP分片与重组。子网划分和CIDR。特殊IP地址：0.0.0.0、127.0.0.1、255.255.255.255。\n\n在实际开发中，IP协议的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nIP协议是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (179, 16, 4, 'ARP协议', '第ARP协议\n\n本章深入探讨ARP协议的核心概念与实践应用。\n\nARP（地址解析协议）将IP地址映射为MAC地址。ARP工作过程：广播ARP请求，目标主机单播ARP应答。ARP缓存减少广播。免费ARP用于检测IP冲突和更新其他主机的ARP缓存。代理ARP允许路由器代替其他网络的主机回应ARP请求。\n\n在实际开发中，ARP协议的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nARP协议是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (180, 16, 5, 'RARP协议', '第RARP协议\n\n本章深入探讨RARP协议的核心概念与实践应用。\n\nRARP（逆地址解析协议）将MAC地址映射为IP地址，用于无盘工作站启动时获取IP。RARP已基本被BOOTP和DHCP取代。DHCP（动态主机配置协议）：DISCOVER→OFFER→REQUEST→ACK四步获取IP地址及其他网络配置。\n\n在实际开发中，RARP协议的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nRARP协议是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (181, 16, 6, 'ICMP协议', '第ICMP协议\n\n本章深入探讨ICMP协议的核心概念与实践应用。\n\nICMP（因特网控制报文协议）用于网络层的差错报告和查询。ICMP报文类型：回显请求/应答（ping）、目的不可达、超时、重定向。ICMP是IP协议的重要补充，帮助诊断网络问题。\n\n在实际开发中，ICMP协议的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nICMP协议是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (182, 16, 7, 'Ping程序', '第Ping程序\n\n本章深入探讨Ping程序的核心概念与实践应用。\n\nPing使用ICMP回显请求和回显应答报文测试网络连通性。Ping输出：RTT（往返时间）、TTL、丢包率。Ping的实现原理：发送ICMP Echo Request，接收ICMP Echo Reply。常用选项：-c指定次数、-i指定间隔、-t指定TTL。\n\n在实际开发中，Ping程序的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nPing程序是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (183, 16, 8, 'Traceroute程序', '第Traceroute程序\n\n本章深入探讨Traceroute程序的核心概念与实践应用。\n\nTraceroute通过逐步增加TTL来发现到目标的路径。原理：发送TTL=1的数据包，第一跳路由器返回ICMP超时；TTL=2，第二跳返回超时...直到到达目标。Windows下为tracert命令，Linux下为traceroute。\n\n在实际开发中，Traceroute程序的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nTraceroute程序是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (184, 16, 9, 'IP选路', '第IP选路\n\n本章深入探讨IP选路的核心概念与实践应用。\n\nIP选路（路由）决定数据包的转发路径。路由表：目的网络、下一跳、接口。静态路由和动态路由。路由协议：RIP（距离向量，跳数限制15）、OSPF（链路状态，Dijkstra算法）、BGP（路径向量，自治系统间路由）。默认路由和主机路由。\n\n在实际开发中，IP选路的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nIP选路是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (185, 16, 10, 'UDP协议', '第UDP协议\n\n本章深入探讨UDP协议的核心概念与实践应用。\n\nUDP（用户数据报协议）是无连接的传输层协议。UDP头部只有8字节：源端口、目的端口、长度、校验和。UDP的特点：无连接、不可靠、无流量控制、无拥塞控制、开销小。UDP适用场景：DNS查询、DHCP、实时音视频、游戏。\n\n在实际开发中，UDP协议的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nUDP协议是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (186, 16, 11, 'TCP概述', '第TCP概述\n\n本章深入探讨TCP概述的核心概念与实践应用。\n\nTCP（传输控制协议）提供面向连接的可靠字节流服务。TCP头部：源端口、目的端口、序列号、确认号、标志位（SYN/ACK/FIN/RST/PSH/URG）、窗口大小、校验和。TCP的可靠性机制：序列号确认、超时重传、流量控制（滑动窗口）、拥塞控制。\n\n在实际开发中，TCP概述的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nTCP概述是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (187, 16, 12, 'TCP连接管理', '第TCP连接管理\n\n本章深入探讨TCP连接管理的核心概念与实践应用。\n\n三次握手建立连接：客户端SYN(seq=x)→服务器SYN+ACK(seq=y,ack=x+1)→客户端ACK(ack=y+1)。四次挥手断开连接：FIN→ACK→FIN→ACK。TIME_WAIT状态：主动关闭方等待2MSL。半关闭：一端关闭发送但仍可接收。TCP状态机：CLOSED→SYN_SENT→ESTABLISHED→FIN_WAIT_1→TIME_WAIT→CLOSED。\n\n在实际开发中，TCP连接管理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nTCP连接管理是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (188, 17, 1, '导论', '第导论\n\n本章深入探讨导论的核心概念与实践应用。\n\n操作系统是管理计算机硬件与软件资源的程序。操作系统的主要功能：进程管理、内存管理、文件系统管理、设备管理。操作系统的发展：批处理系统→多道程序系统→分时系统→个人计算机→分布式系统→实时系统。内核模式与用户模式。系统调用是用户程序与操作系统的接口。\n\n在实际开发中，导论的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n导论是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (189, 17, 2, '操作系统结构', '第操作系统结构\n\n本章深入探讨操作系统结构的核心概念与实践应用。\n\n操作系统服务：用户界面、程序执行、I/O操作、文件系统操作、通信、错误检测。系统调用类型：进程控制、文件管理、设备管理、信息维护、通信。操作系统结构：简单结构、分层方法、微内核、模块、混合系统。Linux采用宏内核设计。\n\n在实际开发中，操作系统结构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n操作系统结构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (190, 17, 3, '进程', '第进程\n\n本章深入探讨进程的核心概念与实践应用。\n\n进程是操作系统资源分配的基本单位。进程状态：新建→就绪→运行→等待→终止。进程控制块（PCB）包含进程状态、程序计数器、CPU寄存器、调度信息、内存管理信息等。进程间通信（IPC）：共享内存和消息传递。\n\n在实际开发中，进程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n进程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (191, 17, 4, '线程与并发', '第线程与并发\n\n本章深入探讨线程与并发的核心概念与实践应用。\n\n线程是CPU调度的基本单位。同一进程的线程共享代码段、数据段和操作系统资源。多线程模型：多对一、一对一、多对多。用户级线程vs内核级线程。线程库：POSIX Threads、Windows Threads、Java Threads。线程池减少线程创建销毁的开销。\n\n在实际开发中，线程与并发的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n线程与并发是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (192, 17, 5, 'CPU调度', '第CPU调度\n\n本章深入探讨CPU调度的核心概念与实践应用。\n\nCPU调度算法：先来先服务（FCFS）、最短作业优先（SJF）、优先级调度、轮转调度（RR）、多级队列调度、多级反馈队列调度。调度准则：CPU利用率、吞吐量、周转时间、等待时间、响应时间。抢占式vs非抢占式调度。Linux的CFS（完全公平调度器）。\n\n在实际开发中，CPU调度的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nCPU调度是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (193, 17, 6, '进程同步', '第进程同步\n\n本章深入探讨进程同步的核心概念与实践应用。\n\n同步与互斥：临界区问题要求互斥、前进和有限等待。互斥锁(Mutex)保证同一时刻只有一个线程进入临界区。信号量(Semaphore)是更通用的同步工具。经典同步问题：生产者-消费者问题、读者-写者问题、哲学家进餐问题。管程(Monitor)提供更高级的同步抽象。\n\n在实际开发中，进程同步的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n进程同步是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (194, 17, 7, '同步示例', '第同步示例\n\n本章深入探讨同步示例的核心概念与实践应用。\n\n经典同步问题的实现：有界缓冲区问题（生产者-消费者）、读者-写者问题（读写锁）、哲学家进餐问题（避免死锁的策略）。Windows同步原语：临界区对象、互斥对象、信号量、事件。Linux同步原语：pthread_mutex、pthread_cond、sem_t。\n\n在实际开发中，同步示例的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n同步示例是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (195, 17, 8, '死锁', '第死锁\n\n本章深入探讨死锁的核心概念与实践应用。\n\n死锁的四个必要条件：互斥、占有并等待、非抢占、循环等待。死锁处理策略：预防（破坏四个条件之一）、避免（银行家算法）、检测（资源分配图）、恢复（终止进程或资源抢占）。实际系统中多采用鸵鸟算法——忽略死锁问题，由程序员来避免。\n\n在实际开发中，死锁的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n死锁是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (196, 17, 9, '主存', '第主存\n\n本章深入探讨主存的核心概念与实践应用。\n\n内存管理：连续内存分配（首次适应、最佳适应、最差适应）。分页：将物理内存划分为固定大小的页框，逻辑地址空间划分为同样大小的页。页表将虚拟页号映射到物理帧号。TLB（快表）加速地址转换。多级页表减少页表占用空间。\n\n在实际开发中，主存的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n主存是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (197, 17, 10, '虚拟内存', '第虚拟内存\n\n本章深入探讨虚拟内存的核心概念与实践应用。\n\n虚拟内存允许程序使用比物理内存更大的地址空间。请求分页：只在需要时才将页面载入内存。页面置换算法：FIFO（先进先出）、OPT（最优，理论上界）、LRU（最近最少使用）、Clock（时钟算法，LRU近似）。颠簸(Thrashing)：频繁页面置换导致系统效率急剧下降。工作集模型。\n\n在实际开发中，虚拟内存的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n虚拟内存是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (198, 17, 11, '大容量存储结构', '第大容量存储结构\n\n本章深入探讨大容量存储结构的核心概念与实践应用。\n\n磁盘结构：磁道、扇区、柱面。磁盘调度算法：FCFS、SSTF（最短寻道时间优先）、SCAN（电梯算法）、C-SCAN。SSD（固态硬盘）：无机械部件、随机访问快、存在写入寿命问题。RAID（磁盘冗余阵列）：通过冗余提高可靠性和性能。\n\n在实际开发中，大容量存储结构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n大容量存储结构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (199, 17, 12, '文件系统', '第文件系统\n\n本章深入探讨文件系统的核心概念与实践应用。\n\n文件系统将数据组织为文件和目录的层次结构。常见文件系统：ext4（Linux默认）、NTFS（Windows）、APFS（macOS）。文件分配方式：连续分配、链接分配、索引分配。空闲空间管理：位图、链表。日志文件系统通过写前日志保证崩溃一致性。\n\n在实际开发中，文件系统的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n文件系统是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (200, 18, 1, '计算机系统漫游', '第计算机系统漫游\n\n本章深入探讨计算机系统漫游的核心概念与实践应用。\n\n计算机系统由硬件和系统软件组成。程序的生命周期：编写→预处理→编译→汇编→链接→加载→执行。存储器层次结构利用了局部性原理。操作系统提供抽象：进程、虚拟内存、文件。Amdahl定律：加速比受不可加速部分限制。\n\n在实际开发中，计算机系统漫游的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n计算机系统漫游是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (201, 18, 2, '信息的表示和处理', '第信息的表示和处理\n\n本章深入探讨信息的表示和处理的核心概念与实践应用。\n\n信息存储：字节编址、大端vs小端。整数表示：无符号编码、补码编码。整数运算：溢出的危险。浮点数表示：IEEE 754标准，单精度32位、双精度64位。浮点数的精度问题：0.1+0.2!=0.3。\n\n在实际开发中，信息的表示和处理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n信息的表示和处理是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (202, 18, 3, '程序的机器级表示', '第程序的机器级表示\n\n本章深入探讨程序的机器级表示的核心概念与实践应用。\n\nx86-64汇编基础：寄存器、操作数格式、数据传送指令（MOV）、算术逻辑指令。控制流：条件码、跳转指令、条件传送。过程（函数调用）：栈帧、参数传递、返回值。数组和结构体的机器级表示。\n\n在实际开发中，程序的机器级表示的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n程序的机器级表示是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (203, 18, 4, '处理器体系结构', '第处理器体系结构\n\n本章深入探讨处理器体系结构的核心概念与实践应用。\n\n指令集架构（ISA）定义处理器的编程接口。Y86-64指令集。顺序实现（SEQ）：取指→译码→执行→访存→写回→更新PC。流水线实现（PIPE）：通过重叠执行提高吞吐量。流水线冒险：数据冒险（转发、暂停）、控制冒险（分支预测）。\n\n在实际开发中，处理器体系结构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n处理器体系结构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (204, 18, 5, '优化程序性能', '第优化程序性能\n\n本章深入探讨优化程序性能的核心概念与实践应用。\n\n编译器优化能力和局限性。消除不必要的计算：代码移动、减少过程调用、消除不必要的内存引用。利用指令级并行：循环展开、多个累积变量、重新结合变换。理解处理器的运算单元和延迟。性能分析工具：profiler。\n\n在实际开发中，优化程序性能的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n优化程序性能是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (205, 18, 6, '存储器层次结构', '第存储器层次结构\n\n本章深入探讨存储器层次结构的核心概念与实践应用。\n\n存储器层次结构利用了局部性原理来弥合处理器速度和内存速度之间的差距。层次结构：寄存器→L1缓存→L2缓存→L3缓存→主存→磁盘→远程存储。缓存命中与缓存不命中。缓存组织：直接映射、组相联、全相联。写策略：写直达、写回。缓存友好代码：保持良好的时间局部性和空间局部性。\n\n在实际开发中，存储器层次结构的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n存储器层次结构是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (206, 18, 7, '链接', '第链接\n\n本章深入探讨链接的核心概念与实践应用。\n\n链接器的作用：符号解析和重定位。目标文件格式：ELF（Linux）。静态链接：将所有目标文件合并为一个可执行文件。静态库（.a）。动态链接：运行时加载共享库（.so/.dll）。位置无关代码（PIC）。链接器符号：全局、外部、局部。\n\n在实际开发中，链接的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n链接是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (207, 18, 8, '异常控制流', '第异常控制流\n\n本章深入探讨异常控制流的核心概念与实践应用。\n\n异常控制流（ECF）是操作系统实现并发的基础。异常类型：中断（异步，来自I/O设备）、陷阱（同步，有意的，如系统调用）、故障（同步，可能可恢复，如缺页）、终止（同步，不可恢复）。进程上下文切换。信号机制：Unix系统的软件中断。\n\n在实际开发中，异常控制流的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n异常控制流是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (208, 18, 9, '虚拟内存', '第虚拟内存\n\n本章深入探讨虚拟内存的核心概念与实践应用。\n\n虚拟内存作为缓存：DRAM缓存磁盘上的虚拟页。虚拟内存作为内存管理：简化链接、加载、共享和内存保护。地址翻译：虚拟地址→物理地址，通过页表完成。TLB加速翻译。Linux虚拟内存系统：内核虚拟内存、用户栈、共享库、堆、数据段、代码段。\n\n在实际开发中，虚拟内存的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n虚拟内存是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (209, 18, 10, '系统级I/O', '第系统级I/O\n\n本章深入探讨系统级I/O的核心概念与实践应用。\n\nUnix I/O：一切皆文件。文件描述符。基本I/O函数：open、close、read、write、lseek。文件元数据：stat。标准I/O库提供缓冲。RIO（Robust I/O）包。I/O重定向：dup2。\n\n在实际开发中，系统级I/O的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n系统级I/O是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (210, 18, 11, '网络编程', '第网络编程\n\n本章深入探讨网络编程的核心概念与实践应用。\n\n客户端-服务器模型。套接字接口：socket、bind、listen、accept、connect。Web服务器的基本工作原理。HTTP请求和响应。CGI（通用网关接口）。并发服务器：基于进程、基于线程、基于I/O多路复用（select/poll/epoll）。\n\n在实际开发中，网络编程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n网络编程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (211, 18, 12, '并发编程', '第并发编程\n\n本章深入探讨并发编程的核心概念与实践应用。\n\n三种并发方式：基于进程（fork）、基于I/O多路复用（select/epoll）、基于线程（pthread）。线程安全：可重入函数、互斥锁保护共享数据。竞争条件和数据竞争。死锁。线程安全的库函数。生产者-消费者模型。线程池。\n\n在实际开发中，并发编程的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n并发编程是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (212, 19, 1, 'Spring起步', '第Spring起步\n\n本章深入探讨Spring起步的核心概念与实践应用。\n\nSpring Framework是Java企业级应用开发的主流框架。核心特性：控制反转（IoC）和依赖注入（DI）。Spring Boot简化了Spring应用的创建和配置。Spring Boot的自动配置、起步依赖和嵌入式服务器。Spring Initializr快速创建项目骨架。\n\n在实际开发中，Spring起步的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nSpring起步是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (213, 19, 2, '开发Web应用', '第开发Web应用\n\n本章深入探讨开发Web应用的核心概念与实践应用。\n\nSpring MVC：@Controller、@RequestMapping、@GetMapping、@PostMapping。视图解析器和模板引擎（Thymeleaf）。表单处理和数据绑定。表单验证（@Valid、@NotNull、@Size等）。RESTful API设计：@RestController、@RequestBody、@ResponseBody。\n\n在实际开发中，开发Web应用的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n开发Web应用是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (214, 19, 3, '使用数据', '第使用数据\n\n本章深入探讨使用数据的核心概念与实践应用。\n\nSpring Data JPA简化数据访问层开发。Repository接口：CrudRepository、JpaRepository。方法名查询约定：findByName、findByAgeGreaterThan。@Query自定义查询。事务管理：@Transactional。JdbcTemplate提供更底层的数据库操作。\n\n在实际开发中，使用数据的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n使用数据是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (215, 19, 4, '保护Spring', '第保护Spring\n\n本章深入探讨保护Spring的核心概念与实践应用。\n\nSpring Security提供认证和授权功能。认证方式：表单登录、HTTP Basic、OAuth2、JWT。授权：基于角色（ROLE_ADMIN）、基于权限。@PreAuthorize和@PostAuthorize方法级安全。CSRF防护。密码加密：BCryptPasswordEncoder。\n\n在实际开发中，保护Spring的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n保护Spring是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (216, 19, 5, '使用配置属性', '第使用配置属性\n\n本章深入探讨使用配置属性的核心概念与实践应用。\n\nSpring Boot外部化配置：application.properties/application.yml。多环境配置：application-dev.yml、application-prod.yml。@ConfigurationProperties绑定配置到Bean。@Value注入单个属性。配置的优先级：命令行参数>环境变量>配置文件。\n\n在实际开发中，使用配置属性的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n使用配置属性是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (217, 19, 6, '创建REST服务', '第创建REST服务\n\n本章深入探讨创建REST服务的核心概念与实践应用。\n\nRESTful API设计原则：资源命名、HTTP方法语义（GET获取、POST创建、PUT更新、DELETE删除）。@RestController、@PathVariable、@RequestParam、@RequestBody。响应状态码：200/201/204/400/404/500。HATEOAS（超媒体驱动）。API版本控制。\n\n在实际开发中，创建REST服务的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n创建REST服务是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (218, 19, 7, '消费REST服务', '第消费REST服务\n\n本章深入探讨消费REST服务的核心概念与实践应用。\n\nRestTemplate是Spring提供的REST客户端。常用方法：getForObject、postForObject、put、delete、exchange。WebClient是响应式的REST客户端（Spring WebFlux）。OpenFeign声明式REST客户端。错误处理和重试机制。\n\n在实际开发中，消费REST服务的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n消费REST服务是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (219, 19, 8, '发送异步消息', '第发送异步消息\n\n本章深入探讨发送异步消息的核心概念与实践应用。\n\n消息队列实现异步通信和解耦。Spring对消息中间件的支持：JMS（ActiveMQ）、AMQP（RabbitMQ）、Kafka。JmsTemplate和RabbitTemplate。@JmsListener和@RabbitListener注解。Kafka的Producer和Consumer。消息可靠性保证。\n\n在实际开发中，发送异步消息的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n发送异步消息是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (220, 19, 9, 'Spring集成', '第Spring集成\n\n本章深入探讨Spring集成的核心概念与实践应用。\n\nSpring Integration实现企业集成模式（EIP）。核心概念：消息、通道、端点。集成流：网关、过滤器、转换器、路由器、分割器、聚合器。DSL配置集成流。常用适配器：文件、HTTP、JMS、JDBC。\n\n在实际开发中，Spring集成的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nSpring集成是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (221, 19, 10, 'Reactor介绍', '第Reactor介绍\n\n本章深入探讨Reactor介绍的核心概念与实践应用。\n\nProject Reactor是Spring 5引入的响应式编程库。核心类型：Mono（0或1个元素）和Flux（0到N个元素）。响应式操作：map、flatMap、filter、zip、merge。背压(Backpressure)机制。Spring WebFlux是基于Reactor的响应式Web框架。\n\n在实际开发中，Reactor介绍的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nReactor介绍是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (222, 19, 11, '开发响应式API', '第开发响应式API\n\n本章深入探讨开发响应式API的核心概念与实践应用。\n\nSpring WebFlux支持两种编程模型：注解式（类似Spring MVC）和函数式（RouterFunction + HandlerFunction）。响应式数据访问：Spring Data R2DBC、Reactive MongoDB。WebClient替代RestTemplate。服务器发送事件（SSE）实现实时推送。\n\n在实际开发中，开发响应式API的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n开发响应式API是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (223, 19, 12, '部署Spring', '第部署Spring\n\n本章深入探讨部署Spring的核心概念与实践应用。\n\nSpring Boot应用可以打包为JAR或WAR。Docker容器化部署。Kubernetes编排。Spring Boot Actuator提供生产级监控端点。健康检查、指标收集、日志管理。Spring Cloud提供微服务基础设施：服务发现（Eureka）、配置中心（Config Server）、API网关（Gateway）、熔断器（Resilience4j）。\n\n在实际开发中，部署Spring的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n部署Spring是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (224, 20, 1, 'Docker入门', '第Docker入门\n\n本章深入探讨Docker入门的核心概念与实践应用。\n\nDocker是一个开源的容器化平台。容器vs虚拟机：容器共享宿主机内核，更轻量。Docker核心概念：镜像（Image，只读模板）、容器（Container，镜像的运行实例）、仓库（Registry，镜像存储）。Docker架构：Docker Daemon、Docker Client、Docker Registry。\n\n在实际开发中，Docker入门的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nDocker入门是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (225, 20, 2, 'Docker镜像', '第Docker镜像\n\n本章深入探讨Docker镜像的核心概念与实践应用。\n\nDockerfile定义镜像构建步骤。常用指令：FROM基础镜像、RUN执行命令、COPY复制文件、WORKDIR工作目录、EXPOSE声明端口、CMD默认启动命令、ENTRYPOINT入口点。镜像层：每条指令创建一层，层可以共享和缓存。多阶段构建减小镜像体积。\n\n在实际开发中，Docker镜像的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nDocker镜像是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (226, 20, 3, '容器管理', '第容器管理\n\n本章深入探讨容器管理的核心概念与实践应用。\n\n容器生命周期：创建→启动→运行→暂停→停止→删除。常用命令：docker run、docker start/stop、docker exec、docker logs、docker ps、docker rm。端口映射：-p host_port:container_port。数据卷：-v实现数据持久化。环境变量：-e传递配置。\n\n在实际开发中，容器管理的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n容器管理是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (227, 20, 4, 'Docker Compose', '第Docker Compose\n\n本章深入探讨Docker Compose的核心概念与实践应用。\n\nDocker Compose用于定义和运行多容器应用。docker-compose.yml文件定义服务、网络和卷。常用命令：docker-compose up、docker-compose down、docker-compose logs、docker-compose ps。服务依赖：depends_on。环境变量和.env文件。\n\n在实际开发中，Docker Compose的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nDocker Compose是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (228, 20, 5, 'Docker网络', '第Docker网络\n\n本章深入探讨Docker网络的核心概念与实践应用。\n\nDocker网络驱动：bridge（默认，单主机容器通信）、host（共享宿主机网络栈）、overlay（跨主机容器通信）、none（无网络）。自定义网络：docker network create。容器间通过服务名通信（DNS解析）。\n\n在实际开发中，Docker网络的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nDocker网络是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (229, 20, 6, 'Docker存储', '第Docker存储\n\n本章深入探讨Docker存储的核心概念与实践应用。\n\nDocker存储类型：数据卷（Volume，Docker管理的存储）、绑定挂载（Bind Mount，映射宿主机目录）、tmpfs挂载（内存存储）。数据卷管理：docker volume create/ls/rm/inspect。数据备份和迁移。存储驱动：overlay2（推荐）。\n\n在实际开发中，Docker存储的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nDocker存储是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (230, 20, 7, 'Docker安全', '第Docker安全\n\n本章深入探讨Docker安全的核心概念与实践应用。\n\nDocker安全最佳实践：使用最小基础镜像（alpine）、不以root运行容器（USER指令）、扫描镜像漏洞、限制容器资源（--memory、--cpus）、使用只读文件系统（--read-only）、Seccomp和AppArmor安全配置。Docker Content Trust签名验证。\n\n在实际开发中，Docker安全的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nDocker安全是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (231, 20, 8, '容器编排', '第容器编排\n\n本章深入探讨容器编排的核心概念与实践应用。\n\nKubernetes（K8s）是主流的容器编排平台。核心概念：Pod（最小部署单元）、Service（服务发现和负载均衡）、Deployment（声明式部署）、ConfigMap/Secret（配置管理）。kubectl常用命令。Docker Swarm是Docker原生的编排工具。\n\n在实际开发中，容器编排的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n容器编排是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (232, 20, 9, 'CI/CD与Docker', '第CI/CD与Docker\n\n本章深入探讨CI/CD与Docker的核心概念与实践应用。\n\n持续集成/持续部署（CI/CD）与Docker结合：Jenkins Pipeline构建Docker镜像、GitLab CI/CD、GitHub Actions。多阶段构建优化CI流程。镜像推送到私有Registry。蓝绿部署和滚动更新。\n\n在实际开发中，CI/CD与Docker的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\nCI/CD与Docker是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (233, 20, 10, '监控与日志', '第监控与日志\n\n本章深入探讨监控与日志的核心概念与实践应用。\n\n容器监控：Prometheus + Grafana收集和展示指标。cAdvisor容器资源监控。日志管理：docker logs查看容器日志。ELK/EFK栈（Elasticsearch + Logstash/Fluentd + Kibana）集中管理日志。日志驱动：json-file（默认）、syslog、fluentd。\n\n在实际开发中，监控与日志的应用无处不在。首先，要深入理解基本原理。其次，要注重代码的可读性和可维护性。\n\n本章小结：\n监控与日志是软件开发中的基础且重要的知识领域。');
INSERT INTO `book_content` VALUES (234, 21, 1, '第1章', '此开卷第一回也。作者自云：因曾历过一番梦幻之后，故将真事隐去，而借“通灵”之说，撰此《石头记》一书也。故曰“甄士隐”云云。但书中所记何事何人？自又云：“今风尘碌碌，一事无成，忽念及当日所有之女子，一一细考校去，觉其行止见识皆出于我之上。何我堂堂须眉，诚不若彼裙钗哉？实愧则有馀，悔又无益之大无可如何之日也！当此，则自欲将已往所赖天恩祖德，锦衣纨袴之时，饫甘餍肥之日，背父兄教育之恩，负师友规训之德，以至今日一技无成，半生潦倒之罪，编述一集，以告天下人：我之罪固不免，然闺阁中本自历历有人，万不可因我之不肖，自护己短，一并使其泯灭也。虽今日之茅椽蓬牖，瓦灶绳床，其晨夕风露，阶柳庭花，亦未有妨我之襟怀笔墨者。虽我未学，下笔无文，又何妨用假语村言，敷演出一段故事来，亦可使闺阁昭传，复可悦世之目，破人愁闷，不亦宜乎？”故曰“贾雨村云云。”\n\n\n　　此回中凡用“梦”用“幻”等字，是提醒阅者眼目，亦是此书立意本旨。\n\n　　列位看官：你道此书从何而来？说起根由虽近荒唐，细按则深有趣味。待在下将此来历注明，方使阅者了然不惑。\n\n　　原来女娲氏炼石补天之时，于大荒山无稽崖炼成高经十二丈，方经二十四丈顽石三万六千五百零一块。娲皇氏只用了三万六千五百块，只单单剩了一块未用，便弃在此山青埂峰下。谁知此石自经煅炼之后，灵性已通，因见众石俱得补天，独自己无材不堪入选，遂自怨自叹，日夜悲号惭愧。\n\n　　一日，正当嗟悼之际，俄见一僧一道远远而来，生得骨格不凡，丰神迥异，说说笑笑来至峰下，坐于石边高谈快论。先是说些云山雾海神仙玄幻之事，后便说到红尘中荣华富贵；此石听了，不觉打动凡心，也想要到人间去享一享这荣华富贵，但自恨粗蠢，不得已，便口吐人言，向那僧道说道：“大师，弟子蠢物，不能见礼了。适闻二位谈那人世间荣耀繁华，心切慕之。弟子质虽粗蠢，性却稍通；况见二师仙形道体，定非凡品，必有补天济世之材，利物济人之德。如蒙发一点慈心，携带弟子得入红尘，在那富贵场中，温柔乡里受享几年，自当永佩洪恩，万劫不忘也。”二仙师听毕，齐憨笑道：“善哉，善哉！那红尘中有却有些乐事，但不能永远依恃，况又有‘美中不足，好事多磨’八个字紧相连属，瞬息间则又乐极悲生，人非物换，究竟是到头一梦，万境归空，倒不如不去的好。”\n\n　　这石凡心已炽，那里听得进这话去，乃复苦求再四。二仙知不可强制，乃叹道：“此亦静极思动，无中生有之数也。既如此，我们便携你去受享受享，只是到不得意时，切莫后悔。”石道：“自然，自然。”那僧又道：“若说你性灵，却又如此质蠢，并更无奇贵之处。如此也只好踮脚而已。也罢，我如今大施佛法助你助，待劫终之日，复还本质，以了此案。你道好否？”石头听了，感谢不尽。那僧便念咒书符，大展幻术，将一块大石登时变成一块鲜明莹洁的美玉，且又缩成扇坠大小的可佩可拿。那僧托于掌上，笑道：“形体倒也是个宝物了！还只没有实在的好处，须得再镌上数字，使人一见便知是奇物方妙。然后携你到那昌明隆盛之邦，诗礼簪缨之族，花柳繁华地，温柔富贵乡去安身乐业。”石头听了，喜不能禁，乃问：“不知赐了弟子哪几件奇处，又不知携了弟子到何地方？望乞明示，使弟子不惑。”那僧笑道：“你且莫问，日后自然明白的。”说着，便袖了这石，同那道人飘然而去，竟不知投奔何方何舍。\n\n　　后来，又不知过了几世几劫，因有个空空道人访道求仙，忽从这大荒山无稽崖青埂峰下经过，忽见一大块石上字迹分明，编述历历。空空道人乃从头一看，原来就是无材补天，幻形入世，蒙茫茫大士渺渺真人携入红尘，历尽离合悲欢炎凉世态的一段故事。后面又有一首偈云：\n\n　　无材可去补苍天，枉入红尘若许年。\n\n　　此系身前身后事，倩谁记去作奇传？\n\n　　诗后便是此石坠落之乡，投胎之处，亲自经历的一段陈迹故事。其中家庭闺阁琐事，以及闲情诗词倒还全备，或可适趣解闷，然朝代年纪、地舆邦国，却反失落无考。\n\n　　空空道人遂向石头说道：“石兄，你这一段故事，据你自己说有些趣味，故编写在此，意欲问世传奇。据我看来，第一件，无朝代年纪可考；第二件，并无大贤大忠理朝廷治风俗的善政，其中只不过几个异样女子，或情或痴，或小才微善，亦无班姑蔡女之德能。我纵抄去，恐世人不爱看呢。”石头笑答道：“我师何太痴耶！若云无朝代可考，今我师竟假借汉唐等年纪添缀，又有何难？但我想，历来野史，皆蹈一辙，莫如我这不借此套者，反倒新奇别致，不过只取其事体情理罢了，又何必拘拘于朝代年纪哉！再者，市井俗人喜看理治之书者甚少，爱适趣闲文者特多。历来野史，或讪谤君相，或贬人妻女，奸淫凶恶，不可胜数。更有一种风月笔墨，其淫秽污臭，涂毒笔墨，坏人子弟，又不可胜数。至若佳人才子等书，则又千部共出一套，且其中终不能不涉于淫滥，以致满纸潘安、子建、西子、文君、不过作者要写出自己的那两首情诗艳赋来，故假拟出男女二人名姓，又必旁出一小人其间拨乱，亦如剧中之小丑然。且鬟婢开口即者也之乎，非文即理。故逐一看去，悉皆自相矛盾，大不近情理之话，竟不如我半世亲睹亲闻的这几个女子，虽不敢说强似前代书中所有之人，但事迹原委，亦可以消愁破闷；也有几首歪诗熟话，可以喷饭供酒。至若离合悲欢，兴衰际遇，则又追踪蹑迹，不敢稍加穿凿，徒为供人之目而反失其真传者。今之人，贫者日为衣食所累，富者又怀不足之心，纵然一时稍闲，又有贪淫恋色，好货寻愁之事，哪里去有工夫看那理治之书？所以我这一段故事，也不愿世人称奇道妙，也不定要世人喜悦检读，只愿他们当那醉淫饱卧之时，或避事去愁之际，把此一玩，岂不省了些寿命筋力？就比那谋虚逐妄，却也省了口舌是非之害，腿脚奔忙之苦。再者，亦令世人换新眼目，不比那些胡牵乱扯，忽离忽遇，满纸才人淑女、子建文君红娘小玉等通共熟套之旧稿。我师意为何如？”\n\n　　空空道人听如此说，思忖半晌，将《石头记》再检阅一遍，因见上面虽有些指奸责佞贬恶诛邪之语，亦非伤时骂世之旨；及至君仁臣良父慈子孝，凡伦常所关之处，皆是称功颂德，眷眷无穷，实非别书之可比。虽其中大旨谈情，亦不过实录其事，又非假拟妄称，一味淫邀艳约、私订偷盟之可比。因毫不干涉时世，方从头至尾抄录回来，问世传奇。从此空空道人因空见色，由色生情，传情入色，自色悟空，遂易名为情僧，改《石头记》为《情僧录》。东鲁孔梅溪则题曰《风月宝鉴》。后因曹雪芹于悼红轩中披阅十载，增删五次，纂成目录，分出章回，则题曰《金陵十二钗》。并题一绝云：\n\n　　满纸荒唐言，一把辛酸泪。\n\n　　都云作者痴，谁解其中味？\n\n　　出则既明，且看石上是何故事。按那石上书云：\n\n　　当日地陷东南，这东南一隅有处曰姑苏，有城曰阊门者，最是红尘中一二等富贵风流之地。这阊门外有个十里街，街内有个仁清巷，巷内有个古庙，因地方窄狭，人皆呼作葫芦庙。庙旁住着一家乡宦，姓甄，名费，字士隐。嫡妻封氏，情性贤淑，深明礼义。家中虽不甚富贵，然本地便也推他为望族了。因这甄士隐禀性恬淡，不以功名为念，每日只以观花修竹、酌酒吟诗为乐，倒是神仙一流人品。只是一件不足：如今年已半百，膝下无儿，只有一女，乳名唤作英莲，年方三岁。\n\n　　一日，炎夏永昼，士隐于书房闲坐，至手倦抛书，伏几少憩，不觉朦胧睡去。梦至一处，不辨是何地方。忽见那厢来了一僧一道，且行且谈。\n\n　　只听道人问道：“你携了这蠢物，意欲何往？”那僧笑道：“你放心，如今现有一段风流公案正该了结，这一干风流冤家，尚未投胎入世。趁此机会，就将此蠢物夹带于中，使他去经历经历。”那道人道：“原来近日风流冤孽又将造劫历世去不成？但不知落于何方何处？”那僧笑道：“此事说来好笑，竟是千古未闻的罕事。只因西方灵河岸上三生石畔，有绛珠草一株，时有赤瑕宫神瑛侍者，日以甘露灌溉，这绛珠草始得久延岁月。后来既受天地精华，复得雨露滋养，遂得脱却草胎木质，得换人形，仅修成个女体，终日游于离恨天外，饥则食蜜青果为膳，渴则饮灌愁海水为汤。只因尚未酬报灌溉之德，故其五内便郁结着一段缠绵不尽之意。恰近日这神瑛侍者凡心偶炽，乘此昌明太平朝世，意欲下凡造历幻缘，已在警幻仙子案前挂了号。警幻亦曾问及，灌溉之情未偿，趁此倒可了结的。那绛珠仙子道：‘他是甘露之惠，我并无此水可还。他既下世为人，我也去下世为人，但把我一生所有的眼泪还他，也偿还得过他了。’因此一事，就勾出多少风流冤家来，陪他们去了结此案。”\n\n　　那道人道：“果是罕闻。实未闻有还泪之说。想来这一段故事，比历来风月事故更加琐碎细腻了。”那僧道：“历来几个风流人物，不过传其大概以及诗词篇章而已；至家庭闺阁中一饮一食，总未述记。再者，大半风月故事，不过偷香窃玉，暗约私奔而已，并不曾将儿女之真情发泄一二。想这一干人入世，其情痴色鬼、贤愚不肖者，悉与前人传述不同矣。”那道人道：“趁此何不你我也去下世度脱几个，岂不是一场功德？”那僧道：“正合吾意，你且同我到警幻仙子宫中，将蠢物交割清楚，待这一干风流孽鬼下世已完，你我再去。如今虽已有一半落尘，然犹未全集。”道人道：“既如此，便随你去来。”\n\n　　却说甄士隐俱听得明白，但不知所云“蠢物”系何东西。遂不禁上前施礼，笑问道：“二仙师请了。”那僧道也忙答礼相问。士隐因说道：“适闻仙师所谈因果，实人世罕闻者。但弟子愚浊，不能洞悉明白，若蒙大开痴顽，备细一闻，弟子则洗耳谛听，稍能警省，亦可免沉沦之苦。”二仙笑道：“此乃玄机不可预泄者。到那时不要忘我二人，便可跳出火坑矣。”士隐听了，不便再问。因笑道：“玄机不可预泄，但适云‘蠢物’，不知为何，或可一见否？”那僧道：“若问此物，倒有一面之缘。”说着，取出递与士隐。\n\n　　士隐接了看时，原来是块鲜明美玉，上面字迹分明，镌着“通灵宝玉”四字，后面还有几行小字。正欲细看时，那僧便说已到幻境，便强从手中夺了去，与道人竟过一大石牌坊，上书四个大字，乃是“太虚幻境”。两边又有一幅对联，道是：\n\n　　假作真时真亦假，无为有处有还无。\n\n　　士隐意欲也跟了过去，方举步时，忽听一声霹雳，有若山崩地陷。士隐大叫一声，定睛一看，只见烈日炎炎，芭蕉冉冉，所梦之事便忘了大半。又见奶母正抱了英莲走来。士隐见女儿越发生得粉妆玉琢，乖觉可喜，便伸手接来，抱在怀内，斗他顽耍一回，又带至街前，看那过会的热闹。\n\n　　方欲进来时，只见从那边来了一僧一道：那僧则癞头跣脚，那道则跛足蓬头，疯疯癫癫，挥霍谈笑而至。及至到了他门前，看见士隐抱着英莲，那僧便大哭起来，又向士隐道：“施主，你把这有命无运、累及爹娘之物，抱在怀内作甚？”士隐听了，知是疯话，也不去睬他。那僧还说：“舍我罢，舍我罢！”士隐不耐烦，便抱女儿撤身要进去，那僧乃指着他大笑，口内念了四句言词道：\n\n　　惯养娇生笑你痴，菱花空对雪澌澌。\n\n　　好防佳节元宵后，便是烟消火灭时。\n\n　　士隐听得明白，心下犹豫，意欲问他们来历。只听道人说道：“你我不必同行，就此分手，各干营生去罢。三劫后，我在北邙山等你，会齐了同往太虚幻境销号。”那僧道：“最妙，最妙！”说毕，二人一去，再不见个踪影了。士隐心中此时自忖：这两个人必有来历，该试一问，如今悔却晚也。\n\n　　这士隐正痴想，忽见隔壁葫芦庙内寄居的一个穷儒──姓贾名化、表字时飞、别号雨村者走了出来。这贾雨村原系胡州人氏，也是诗书仕宦之族，因他生于末世，父母祖宗根基已尽，人口衰丧，只剩得他一身一口，在家乡无益，因进京求取功名，再整基业。自前岁来此，又淹蹇住了，暂寄庙中安身，每日卖字作文为生，故士隐常与他交接。\n\n　　当下雨村见了士隐，忙施礼陪笑道：“老先生倚门伫望，敢是街市上有甚新闻否？”士隐笑道：“非也。适因小女啼哭，引他出来作耍，正是无聊之甚，兄来得正妙，请入小斋一谈，彼此皆可消此永昼。”说着，便令人送女儿进去，自与雨村携手来至书房中。小童献茶。方谈得三五句话，忽家人飞报：“严老爷来拜。”士隐慌的忙起身谢罪道：“恕诳驾之罪，略坐，弟即来陪。”雨村忙起身亦让道：“老先生请便。晚生乃常造之客，稍候何妨。”说着，士隐已出前厅去了。\n\n　　这里雨村且翻弄书籍解闷。忽听得窗外有女子嗽声，雨村遂起身往窗外一看，原来是一个丫鬟，在那里撷花，生得仪容不俗，眉目清明，虽无十分姿色，却亦有动人之处。雨村不觉看的呆了。\n\n　　那甄家丫鬟撷了花，方欲走时，猛抬头见窗内有人，敝巾旧服，虽是贫窘，然生得腰圆背厚，面阔口方，更兼剑眉星眼，直鼻权腮。这丫鬟忙转身回避，心下乃想：“这人生的这样雄壮，却又这样褴褛，想他定是我家主人常说的什么贾雨村了，每有意帮助周济，只是没甚机会。我家并无这样贫窘亲友，想定是此人无疑了。怪道又说他必非久困之人。”如此想来，不免又回头两次。雨村见他回了头，便自为这女子心中有意于他，便狂喜不尽，自为此女子必是个巨眼英雄，风尘中之知己也。一时小童进来，雨村打听得前面留饭，不可久待，遂从夹道中自便出门去了。士隐待客既散，知雨村自便，也不去再邀。\n\n　　一日，早又中秋佳节。士隐家宴已毕，乃又另具一席于书房，却自己步月至庙中来邀雨村。原来雨村自那日见了甄家之婢曾回顾他两次，自为是个知己，便时刻放在心上。今又正值中秋，不免对月有怀，因而口占五言一律云：\n\n　　未卜三生愿，频添一段愁。\n\n　　闷来时敛额，行去几回头。\n\n　　自顾风前影，谁堪月下俦？\n\n　　蟾光如有意，先上玉人楼。\n\n　　雨村吟罢，因又思及平生抱负，苦未逢时，乃又搔首对天长叹，复高吟一联曰：\n\n　　玉在椟中求善价，钗于奁内待时飞。\n\n　　恰值士隐走来听见，笑道：“雨村兄真抱负不浅也！”雨村忙笑道：“不过偶吟前人之句，何敢狂诞至此。”因问：“老先生何兴至此？”士隐笑道：“今夜中秋，俗谓‘团圆之节’，想尊兄旅寄僧房，不无寂寥之感，故特具小酌，邀兄到敝斋一饮，不知可纳芹意否？”雨村听了，并不推辞，便笑道：“既蒙厚爱，何敢拂此盛情。”说着，便同士隐复过这边书院中来。\n\n　　须臾茶毕，早已设下杯盘，那美酒佳肴自不必说。二人归坐，先是款斟漫饮，次渐谈至兴浓，不觉飞觥限斝起来。当时街坊上家家箫管，户户弦歌，当头一轮明月，飞彩凝辉，二人愈添豪兴，酒到杯干。雨村此时已有七八分酒意，狂兴不禁，乃对月寓怀，口号一绝云：\n\n　　时逢三五便团圆，满把晴光护玉栏。\n\n　　天上一轮才捧出，人间万姓仰头看。\n\n　　士隐听了，大叫：“妙哉！吾每谓兄必非久居人下者，今所吟之句，飞腾之兆已见，不日可接履于云霓之上矣。可贺，可贺！”乃亲斟一斗为贺。雨村因干过，叹道：“非晚生酒后狂言，若论时尚之学，晚生也或可去充数沽名，只是目今行囊路费一概无措，神京路远，非赖卖字撰文即能到者。”士隐不待说完，便道：“兄何不早言。愚每有此心，但每遇兄时，兄并未谈及，愚故未敢唐突。今既及此，愚虽不才，‘义利’二字却还识得。且喜明岁正当大比，兄宜作速入都，春闱一战，方不负兄之所学也。其盘费馀事，弟自代为处置，亦不枉兄之谬识矣！”当下即命小童进去，速封五十两白银，并两套冬衣。又云：“十九日乃黄道之期，兄可即买舟西上，待雄飞高举，明冬再晤，岂非大快之事耶！”雨村收了银衣，不过略谢一语，并不介意，仍是吃酒谈笑。那天已交了三更，二人方散。\n\n　　士隐送雨村去后，回房一觉，直至红日三竿方醒。因思昨夜之事，意欲再写两封荐书与雨村带至神都，使雨村投谒个仕宦之家为寄足之地。因使人过去请时，那家人去了回来说：“和尚说，贾爷今日五鼓已进京去了，也曾留下话与和尚转达老爷，说‘读书人不在黄道黑道，总以事理为要，不及面辞了。’”士隐听了，也只得罢了。\n\n　　真是闲处光阴易过，倏忽又是元宵佳节矣。士隐命家人霍启抱了英莲去看社火花灯，半夜中，霍启因要小解，便将英莲放在一家门槛上坐着。待他小解完了来抱时，哪有英莲的踪影？急得霍启直寻了半夜，至天明不见，那霍启也就不敢回来见主人，便逃往他乡去了。那士隐夫妇，见女儿一夜不归，便知有些不妥，再使几人去寻找，回来皆云连音响皆无。夫妻二人，半世只生此女，一旦失落，岂不思想，因此昼夜啼哭，几乎不曾寻死。看看的一月，士隐先就得了一病，当时封氏孺人也因思女构疾，日日请医疗治。\n\n　　不想这日三月十五，葫芦庙中炸供，那些和尚不加小心，致使油锅火逸，便烧着窗纸。此方人家多用竹篱木壁者，大抵也因劫数，于是接二连三，牵五挂四，将一条街烧得如火焰山一般。彼时虽有军民来救，那火已成了势，如何救得下？直烧了一夜，方渐渐的熄去，也不知烧了几家。只可怜甄家在隔壁，早已烧成一片瓦砾场了。只有他夫妇并几个家人的性命不曾伤了。急得士隐惟跌足长叹而已。只得与妻子商议，且到田庄上去安身。偏值近年水旱不收，鼠盗蜂起，无非抢田夺地，鼠窃狗偷，民不安生，因此官兵剿捕，难以安身。士隐只得将田庄都折变了，便携了妻子与两个丫鬟投他岳丈家去。\n\n　　他岳丈名唤封肃，本贯大如州人氏，虽是务农，家中都还殷实。今见女婿这等狼狈而来，心中便有些不乐。幸而士隐还有折变田地的银子未曾用完，拿出来托他随分就价薄置些须房地，为后日衣食之计。那封肃便半哄半赚，些须与他些薄田朽屋。士隐乃读书之人，不惯生理稼穑等事，勉强支持了一二年，越觉穷了下去。封肃每见面时，便说些现成话，且人前人后又怨他们不善过活，只一味好吃懒作等语。士隐知投人不着，心中未免悔恨，再兼上年惊唬，急忿怨痛，已有积伤，暮年之人，贫病交攻，竟渐渐的露出那下世的光景来。\n\n　　可巧这日拄了拐杖挣挫到街前散散心时，忽见那边来了一个跛足道人，疯癫落脱，麻屣鹑衣，口内念着几句言词，道是：\n\n　　世人都晓神仙好，惟有功名忘不了！\n\n　　古今将相在何方？荒冢一堆草没了。\n\n　　世人都晓神仙好，只有金银忘不了！\n\n　　终朝只恨聚无多，及到多时眼闭了。\n\n　　世人都晓神仙好，只有娇妻忘不了！\n\n　　君生日日说恩情，君死又随人去了。\n\n　　世人都晓神仙好，只有儿孙忘不了！\n\n　　痴心父母古来多，孝顺儿孙谁见了？\n\n　　士隐听了，便迎上来道：“你满口说些什么？只听见些‘好’‘了’‘好’‘了’。”那道人笑道：“你若果听见‘好’‘了’二字，还算你明白。可知世上万般，好便是了，了便是好。若不了，便不好；若要好，须是了。我这歌儿，便名《好了歌》”士隐本是有宿慧的，一闻此言，心中早已彻悟。因笑道：“且住！待我将你这《好了歌》解注出来何如？”道人笑道：“你解，你解。”士隐乃说道：\n\n　　陋室空堂，当年笏满床；衰草枯杨，曾为歌舞场。\n\n　　蛛丝儿结满雕梁，绿纱今又糊在蓬窗上。说什么脂正浓，粉正香，如何两鬓又成霜？\n\n　　昨日黄土陇头送白骨，今宵红灯帐底卧鸳鸯。\n\n　　金满箱，银满箱，转眼乞丐人皆谤。\n\n　　正叹他人命不长，那知自己归来丧！\n\n　　训有方，保不定日后作强梁。择膏粱，谁承望流落在烟花巷！\n\n　　因嫌纱帽小，致使锁枷扛，昨怜破袄寒，今嫌紫蟒长。\n\n　　乱烘烘你方唱罢我登场，反认他乡是故乡。甚荒唐，到头来都是为他人作嫁衣裳！\n\n　　那疯跛道人听了，拍掌笑道：“解得切，解得切！”士隐便说一声“走罢！”将道人肩上褡裢抢了过来背着，竟不回家，同了疯道人飘飘而去。当下烘动街坊，众人当作一件新闻传说。封氏闻得此信，哭个死去活来，只得与父亲商议，遣人各处访寻，哪讨音信？无奈何，少不得依靠着他父母度日。幸而身边还有两个旧日的丫鬟伏侍，主仆三人，日夜作些针线发卖，帮着父亲用度。那封肃虽然日日抱怨，也无可奈何了。\n\n　　这日，那甄家大丫鬟在门前买线，忽听街上喝道之声，众人都说新太爷到任。丫鬟于是隐在门内看时，只见军牢快手，一对一对的过去，俄而大轿抬着一个乌帽猩袍的官府过去。丫鬟倒发了个怔，自思这官好面善，倒像在哪里见过的。于是进入房中，也就丢过不在心上。至晚间，正待歇息之时，忽听一片声打的门响，许多人乱嚷，说：“本府太爷差人来传人问话。”封肃听了，唬得目瞪口呆，不知有何祸事。');
INSERT INTO `book_content` VALUES (235, 21, 2, '第2章', '666');
INSERT INTO `book_content` VALUES (236, 21, 3, '第3章', '却说雨村忙回头看时，不是别人，乃是当日同僚一案参革的号张如圭者。他本系此地人，革后家居，今打听得都中奏准起复旧员之信，他便四下里寻情找门路，忽遇见雨村，故忙道喜。二人见了礼，张如圭便将此信告诉雨村，雨村自是欢喜，忙忙的叙了两句，遂作别各自回家。冷子兴听得此言，便忙献计，令雨村央烦林如海，转向都中去央烦贾政。雨村领其意，作别回至馆中，忙寻邸报看真确了。\n\n　　次日，面谋之如海。如海道：“天缘凑巧，因贱荆去世，都中家岳母念及小女无人依傍教育，前已遣了男女船只来接，因小女未曾大痊，故未及行。此刻正思向蒙训教之恩未经酬报，遇此机会，岂有不尽心图报之理。但请放心。弟已预为筹画至此，已修下荐书一封，转托内兄务为周全协佐，方可稍尽弟之鄙诚，即有所费用之例，弟于内兄信中已注明白，亦不劳尊兄多虑矣。”雨村一面打恭，谢不释口，一面又问：“不知令亲大人现居何职？只怕晚生草率，不敢骤然入都干渎。”如海笑道：“若论舍亲，与尊兄犹系同谱，乃荣公之孙：大内兄现袭一等将军，名赦，字恩侯，二内兄名政，字存周，现任工部员外郎，其为人谦恭厚道，大有祖父遗风，非膏粱轻薄仕宦之流，故弟方致书烦托。否则不但有污尊兄之清操，即弟亦不屑为矣。”雨村听了，心下方信了昨日子兴之言，于是又谢了林如海。如海乃说：“已择了出月初二日小女入都，尊兄即同路而往，岂不两便？”雨村唯唯听命，心中十分得意。如海遂打点礼物并饯行之事，雨村一一领了。\n\n　　那女学生黛玉，身体方愈，原不忍弃父而往，无奈他外祖母致意务去，且兼如海说：“汝父年将半百，再无续室之意，且汝多病，年又极小，上无亲母教养，下无姊妹兄弟扶持，今依傍外祖母及舅氏姊妹去，正好减我顾盼之忧，何反云不往？”黛玉听了，方洒泪拜别，随了奶娘及荣府几个老妇人登舟而去。雨村另有一只船，带两个小童，依附黛玉而行。\n\n　　有日到了都中，进入神京，雨村先整了衣冠，带了小童，拿着宗侄的名帖，至荣府的门前投了。彼时贾政已看了妹丈之书，即忙请入相会。见雨村相貌魁伟，言语不俗，且这贾政最喜读书人，礼贤下士，济弱扶危，大有祖风；况又系妹丈致意，因此优待雨村，更又不同，便竭力内中协助，题奏之日，轻轻谋了一个复职候缺，不上两个月，金陵应天府缺出，便谋补了此缺，拜辞了贾政，择日上任去了。不在话下。\n\n　　且说黛玉自那日弃舟登岸时，便有荣国府打发了轿子并拉行李的车辆久候了。这林黛玉常听得母亲说过，他外祖母家与别家不同。他近日所见的这几个三等仆妇，吃穿用度，已是不凡了，何况今至其家。因此步步留心，时时在意，不肯轻易多说一句话，多行一步路，惟恐被人耻笑了他去。自上了轿，进入城中从纱窗向外瞧了一瞧，其街市之繁华，人烟之阜盛，自与别处不同。又行了半日，忽见街北蹲着两个大石狮子，三间兽头大门，门前列坐着十来个华冠丽服之人。正门却不开，只有东西两角门有人出入。正门之上有一匾，匾上大书“敕造宁国府”五个大字。黛玉想道：这必是外祖之长房了。想着，又往西行，不多远，照样也是三间大门，方是荣国府了。却不进正门，只进了西边角门。那轿夫抬进去，走了一射之地，将转弯时，便歇下退出去了。后面的婆子们已都下了轿，赶上前来。另换了三四个衣帽周全十七八岁的小厮上来，复抬起轿子。众婆子步下围随至一垂花门前落下。众小厮退出，众婆子上来打起轿帘，扶黛玉下轿。林黛玉扶着婆子的手，进了垂花门，两边是抄手游廊，当中是穿堂，当地放着一个紫檀架子大理石的大插屏。转过插屏，小小的三间厅，厅后就是后面的正房大院。正面五间上房，皆雕梁画栋，两边穿山游廊厢房，挂着各色鹦鹉，画眉等鸟雀。台矶之上，坐着几个穿红着绿的丫头，一见他们来了，便忙都笑迎上来，说：“刚才老太太还念呢，可巧就来了。”于是三四人争着打起帘笼，一面听得人回话：“林姑娘到了。”\n\n　　黛玉方进入房时，只见两个人搀着一位鬓发如银的老母迎上来，黛玉便知是他外祖母。方欲拜见时，早被他外祖母一把搂入怀中，心肝儿肉叫着大哭起来。当下地下侍立之人，无不掩面涕泣，黛玉也哭个不住。一时众人慢慢解劝住了，黛玉方拜见了外祖母。－－此即冷子兴所云之史氏太君，贾赦贾政之母也。当下贾母一一指与黛玉：“这是你大舅母，这是你二舅母，这是你先珠大哥的媳妇珠大嫂子。”黛玉一一拜见过。贾母又说：“请姑娘们来。今日远客才来，可以不必上学去了。”众人答应了一声，便去了两个。\n\n　　不一时，只见三个奶嬷嬷并五六个丫鬟，簇拥着三个姊妹来了。第一个肌肤微丰，合中身材，腮凝新荔，鼻腻鹅脂，温柔沉默，观之可亲。第二个削肩细腰，长挑身材，鸭蛋脸面，俊眼修眉，顾盼神飞，文彩精华，见之忘俗。第三个身量未足，形容尚小。其钗环裙袄，三人皆是一样的妆饰。黛玉忙起身迎上来见礼，互相厮认过，大家归了坐。丫鬟们斟上茶来。不过说些黛玉之母如何得病，如何请医服药，如何送死发丧。不免贾母又伤感起来，因说：“我这些儿女，所疼者独有你母，今日一旦先舍我而去，连面也不能一见，今见了你，我怎不伤心！”说着，搂了黛玉在怀，又呜咽起来。众人忙都宽慰解释，方略略止住。\n\n　　众人见黛玉年貌虽小，其举止言谈不俗，身体面庞虽怯弱不胜，却有一段自然的风流态度，便知他有不足之症。因问：“常服何药，如何不急为疗治？”黛玉道：“我自来是如此，从会吃饮食时便吃药，到今日未断，请了多少名医修方配药，皆不见效。那一年我三岁时，听得说来了一个癞头和尚，说要化我去出家，我父母固是不从。他又说：既舍不得他，只怕他的病一生也不能好的了。若要好时，除非从此以后总不许见哭声，除父母之外，凡有外姓亲友之人，一概不见，方可平安了此一世。’疯疯癫癫，说了这些不经之谈，也没人理他。如今还是吃人参养荣丸。”贾母道：“正好，我这里正配丸药呢。叫他们多配一料就是了。\n\n　　一语未了，只听后院中有人笑声，说：“我来迟了，不曾迎接远客！”黛玉纳罕道：“这些人个个皆敛声屏气，恭肃严整如此，这来者系谁，这样放诞无礼？”心下想时，只见一群媳妇丫鬟围拥着一个人从后房门进来。这个人打扮与众姑娘不同，彩绣辉煌，恍若神妃仙子：头上戴着金丝八宝攒珠髻，绾着朝阳五凤挂珠钗，项上戴着赤金盘螭璎珞圈，裙边系着豆绿宫绦双衡比目玫瑰珮，身上穿着缕金百蝶穿花大红洋缎窄裉袄，外罩五彩刻丝石青银鼠褂，下着翡翠撒花洋绉裙。一双丹凤三角眼，两弯柳叶吊梢眉，身量苗条，体格风骚，粉面含春威不露，丹唇未启笑先闻。黛玉连忙起身接见。贾母笑道：“你不认得他，他是我们这里有名的一个泼皮破落户儿，南省俗谓作‘辣子’，你只叫他‘凤辣子’就是了。”黛玉正不知以何称呼，只见众姊妹都忙告诉他道：“这是琏嫂子。”黛玉虽不识，也曾听见母亲说过，大舅贾赦之子贾琏，娶的就是二舅母王氏之内侄女，自幼假充男儿教养的，学名王熙凤。黛玉忙陪笑见礼，以“嫂”呼之。这熙凤携着黛玉的手，上下细细打谅了一回，仍送至贾母身边坐下，因笑道：“天下真有这样标致的人物，我今儿才算见了！况且这通身的气派，竟不像老祖宗的外孙女儿，竟是个嫡亲的孙女，怨不得老祖宗天天口头心头一时不忘。只可怜我这妹妹这样命苦，怎么姑妈偏就去世了！”说着，便用帕拭泪。贾母笑道：“我才好了，你倒来招我。你妹妹远路才来，身子又弱，也才劝住了，快再休提前话。”这熙凤听了，忙转悲为喜道：“正是呢！我一见了妹妹，一心都在他身上了，又是喜欢，又是伤心，竟忘记了老祖宗。该打，该打！”又忙携黛玉之手，问：“妹妹几岁了？可也上过学？现吃什么药？在这里不要想家，想要什么吃的，什么玩的，只管告诉我，丫头老婆们不好了，也只管告诉我。”一面又问婆子们：“林姑娘的行李东西可搬进来了？带了几个人来？你们赶早打扫两间下房，让他们去歇歇。”\n\n　　说话时，已摆了茶果上来。熙凤亲为捧茶捧果。又见二舅母问他：“月钱放过了不曾？”熙凤道：“月钱已放完了。才刚带着人到后楼上找缎子，找了这半日，也并没有见昨日太太说的那样的，想是太太记错了？”王夫人道：“有没有，什么要紧。”因又说道：“该随手拿出两个来给你这妹妹去裁衣裳的，等晚上想着叫人再去拿罢，可别忘了。”熙凤道：“这倒是我先料着了，知道妹妹不过这两日到的，我已预备下了，等太太回去过了目好送来。”王夫人一笑，点头不语。\n\n　　当下茶果已撤，贾母命两个老嬷嬷带了黛玉去见两个母舅。时贾赦之妻邢氏忙亦起身，笑回道：“我带了外甥女过去，倒也便宜。”贾母笑道：“正是呢，你也去罢，不必过来了。”邢夫人答应了一声“是”字，遂带了黛玉与王夫人作辞，大家送至穿堂前。出了垂花门，早有众小厮们拉过一辆翠幄青绸车，邢夫人携了黛玉，坐在上面，众婆子们放下车帘，方命小厮们抬起，拉至宽处，方驾上驯骡，亦出了西角门，往东过荣府正门，便入一黑油大门中，至仪门前方下来。众小厮退出，方打起车帘，邢夫人搀着黛玉的手，进入院中。黛玉度其房屋院宇，必是荣府中花园隔断过来的。进入三层仪门，果见正房厢庑游廊，悉皆小巧别致，不似方才那边轩峻壮丽，且院中随处之树木山石皆在。一时进入正室，早有许多盛妆丽服之姬妾丫鬟迎着，邢夫人让黛玉坐了，一面命人到外面书房去请贾赦。一时人来回话说：“老爷说了：连日身上不好，见了姑娘彼此倒伤心，暂且不忍相见。劝姑娘不要伤心想家，跟着老太太和舅母，即同家里一样。姊妹们虽拙，大家一处伴着，亦可以解些烦闷。或有委屈之处，只管说得，不要外道才是。’”黛玉忙站起来，一一听了。再坐一刻，便告辞。邢夫人苦留吃过晚饭去，黛玉笑回道：“舅母爱惜赐饭，原不应辞，只是还要过去拜见二舅舅，恐领了赐去不恭，异日再领，未为不可。望舅母容谅。”邢夫人听说，笑道：“这倒是了。”遂令两三个嬷嬷用方才的车好生送了姑娘过去，于是黛玉告辞。邢夫人送至仪门前，又嘱咐了众人几句，眼看着车去了方回来。\n\n　　一时黛玉进了荣府，下了车。众嬷嬷引着，便往东转弯，穿过一个东西的穿堂，向南大厅之后，仪门内大院落，上面五间大正房，两边厢房鹿顶耳房钻山，四通八达，轩昂壮丽，比贾母处不同。黛玉便知这方是正经正内室，一条大甬路，直接出大门的。进入堂屋中，抬头迎面先看见一个赤金九龙青地大匾，匾上写着斗大的三个大字，是“荣禧堂”，后有一行小字：“某年月日，书赐荣国公贾源”，又有“万几宸翰之宝”。大紫檀雕螭案上，设着三尺来高青绿古铜鼎，悬着待漏隨潮墨龙大画，一边是金蜼彝，一边是玻璃𥁐。地下两溜十六张楠木交椅，又有一副对联，乃乌木联牌，镶着錾银的字迹，道是：\n\n　　座上珠玑昭日月，堂前黼黻焕烟霞。下面一行小字，道是：“同乡世教弟勋袭东安郡王穆莳拜手书”。\n\n　　原来王夫人时常居坐宴息，亦不在这正室，只在这正室东边的三间耳房内。于是老嬷嬷引黛玉进东房门来。临窗大炕上铺着猩红洋罽，正面设着大红金钱蟒靠背，石青金钱蟒引枕，秋香色金钱蟒大条褥。两边设一对梅花式洋漆小几。左边几上文王鼎匙箸香盒，右边几上汝窑美人觚－－觚内插着时鲜花卉，并茗碗痰盒等物。地下面西一溜四张椅上，都搭着银红撒花椅搭，底下四副脚踏。椅之两边，也有一对高几，几上茗碗瓶花俱备。其余陈设，自不必细说。老嬷嬷们让黛玉炕上坐，炕沿上却有两个锦褥对设，黛玉度其位次，便不上炕，只向东边椅子上坐了。本房内的丫鬟忙捧上茶来。黛玉一面吃茶，一面打谅这些丫鬟们，妆饰衣裙，举止行动，果亦与别家不同。\n\n　　茶未吃了，只见一个穿红绫袄青缎掐牙背心的丫鬟走来笑说道：“太太说，请林姑娘到那边坐罢。”老嬷嬷听了，于是又引黛玉出来，到了东廊三间小正房内。正房炕上横设一张炕桌，桌上磊着书籍茶具，靠东壁面西设着半旧的青缎靠背引枕。王夫人却坐在西边下首，亦是半旧的青缎靠背坐褥。见黛玉来了，便往东让。黛玉心中料定这是贾政之位。因见挨炕一溜三张椅子上，也搭着半旧的弹墨椅袱，黛玉便向椅上坐了。王夫人再四携他上炕，他方挨王夫人坐了。王夫人因说：“你舅舅今日斋戒去了，再见罢。只是有一句话嘱咐你：你三个姊妹倒都极好，以后一处念书认字学针线，或是偶一顽笑，都有尽让的。但我不放心的最是一件：我有一个孽根祸胎，是家里的‘混世魔王’，今日因庙里还愿去了，尚未回来，晚间你看见便知了。你只以后不要睬他，你这些姊妹都不敢沾惹他的。”\n\n　　黛玉亦常听得母亲说过，二舅母生的有个表兄，乃衔玉而诞，顽劣异常，极恶读书，最喜在内帏厮混，外祖母又极溺爱，无人敢管。今见王夫人如此说，便知说的是这表兄了。因陪笑道：“舅母说的，可是衔玉所生的这位哥哥？在家时亦曾听见母亲常说，这位哥哥比我大一岁，小名就唤宝玉，虽极憨顽，说在姊妹情中极好的。况我来了，自然只和姊妹同处，兄弟们自是别院另室的，岂得去沾惹之理？”王夫人笑道：“你不知道原故：他与别人不同，自幼因老太太疼爱，原系同姊妹们一处娇养惯了的。若姊妹们有日不理他，他倒还安静些，纵然他没趣，不过出了二门，背地里拿着他两个小幺儿出气，咕唧一会子就完了。若这一日姊妹们和他多说一句话，他心里一乐，便生出多少事来。所以嘱咐你别睬他。他嘴里一时甜言蜜语，一时有天无日，一时又疯疯傻傻，只休信他。”\n\n　　黛玉一一的都答应着。只见一个丫鬟来回：“老太太那里传晚饭了。”王夫人忙携黛玉从后房门由后廊往西，出了角门，是一条南北宽夹道。南边是倒座三间小小的抱厦厅，北边立着一个粉油大影壁，后有一半大门，小小一所房室。王夫人笑指向黛玉道：“这是你凤姐姐的屋子，回来你好往这里找他来，少什么东西，你只管和他说就是了。”这院门上也有四五个才总角的小厮，都垂手侍立。王夫人遂携黛玉穿过一个东西穿堂，便是贾母的后院了。于是，进入后房门，已有多人在此伺候，见王夫人来了，方安设桌椅。贾珠之妻李氏捧饭，熙凤安箸，王夫人进羹。贾母正面榻上独坐，两边四张空椅，熙凤忙拉了黛玉在左边第一张椅上坐了，黛玉十分推让。贾母笑道：“你舅母你嫂子们不在这里吃饭。你是客，原应如此坐的。”黛玉方告了座，坐了。贾母命王夫人坐了。迎春姊妹三个告了座方上来。迎春便坐右手第一，探春左第二，惜春右第二。旁边丫鬟执着拂尘，漱盂，巾帕。李，凤二人立于案旁布让。外间伺候之媳妇丫鬟虽多，却连一声咳嗽不闻。寂然饭毕，各有丫鬟用小茶盘捧上茶来。当日林如海教女以惜福养身，云饭后务待饭粒咽尽，过一时再吃茶，方不伤脾胃。今黛玉见了这里许多事情不合家中之式，不得不随的，少不得一一改过来，因而接了茶。早见人又捧过漱盂来，黛玉也照样漱了口。盥手毕，又捧上茶来，这方是吃的茶。贾母便说：“你们去罢，让我们自在说话儿。”王夫人听了，忙起身，又说了两句闲话，方引凤，李二人去了。贾母因问黛玉念何书。黛玉道：“只刚念了《四书》。”黛玉又问姊妹们读何书。贾母道：“读的是什么书，不过是认得两个字，不是睁眼的瞎子罢了！”\n\n　　一语未了，只听外面一阵脚步响，丫鬟进来笑道：“宝玉来了！”黛玉心中正疑惑着：“这个宝玉，不知是怎生个惫懒人物，懵懂顽童？－－倒不见那蠢物也罢了。心中想着，忽见丫鬟话未报完，已进来了一位年轻的公子：头上戴着束发嵌宝紫金冠，齐眉勒着二龙抢珠金抹额，穿一件二色金百蝶穿花大红箭袖，束着五彩丝攒花结长穗宫绦，外罩石青起花八团倭缎排穗褂，登着青缎粉底小朝靴。面若中秋之月，色如春晓之花，鬓若刀裁，眉如墨画，面如桃瓣，目若秋波。虽怒时而若笑，即瞋视而有情。项上金螭璎珞，又有一根五色丝绦，系着一块美玉。黛玉一见，便吃一大惊，心下想道：“好生奇怪，倒像在那里见过一般，何等眼熟到如此！”只见这宝玉向贾母请了安，贾母便命：“去见你娘来。”宝玉即转身去了。一时回来，再看，已换了冠带：头上周围一转的短发，都结成小辫，红丝结束，共攒至顶中胎发，总编一根大辫，黑亮如漆，从顶至梢，一串四颗大珠，用金八宝坠角，身上穿着银红撒花半旧大袄，仍旧带着项圈，宝玉，寄名锁，护身符等物，下面半露松花撒花绫裤腿，锦边弹墨袜，厚底大红鞋。越显得面如敷粉，唇若施脂，转盼多情，语言常笑。天然一段风骚，全在眉梢；平生万种情思，悉堆眼角。看其外貌最是极好，却难知其底细。后人有《西江月》二词，批宝玉极恰，其词曰：\n\n　　无故寻愁觅恨，有时似傻如狂。纵然生得好皮囊，腹内原来草莽。\n\n　　潦倒不通世务，愚顽怕读文章。行为偏僻性乖张，那管世人诽谤！\n\n　　富贵不知乐业，贫穷难耐凄凉。可怜辜负好韶光，于国于家无望。\n\n　　天下无能第一，古今不肖无双。寄言纨袴​与膏粱：莫效此儿形状！\n\n　　贾母因笑道：“外客未见，就脱了衣裳，还不去见你妹妹！”宝玉早已看见多了一个姊妹，便料定是林姑妈之女，忙来作揖。厮见毕归坐，细看形容，与众各别：两弯似蹙非蹙罥烟眉，一双似喜非喜含情目。态生两靥之愁，娇袭一身之病。泪光点点，娇喘微微。闲静时如姣花照水，行动处似弱柳扶风。心较比干多一窍，病如西子胜三分。宝玉看罢，因笑道：“这个妹妹我曾见过的。”贾母笑道：“可又是胡说，你又何曾见过他？”宝玉笑道：“虽然未曾见过他，然我看着面善，心里就算是旧相识，今日只作远别重逢，亦未为不可。”贾母笑道：“更好，更好，若如此，更相和睦了。”宝玉便走近黛玉身边坐下，又细细打量一番，因问：“妹妹可曾读书？”黛玉道：“不曾读，只上了一年学，些须认得几个字。”宝玉又道：“妹妹尊名是那两个字？”黛玉便说了名。宝玉又问表字。黛玉道：“无字。”宝玉笑道：“我送妹妹一妙字，莫若‘颦颦’二字极妙。”探春便问何出。宝玉道：“《古今人物通考》上说：‘西方有石名黛，可代画眉之墨。’况这林妹妹眉尖若蹙，用取这两个字，岂不两妙！”探春笑道：“只恐又是你的杜撰。”宝玉笑道：“除《四书》外，杜撰的太多，偏只我是杜撰不成？”又问黛玉：“可也有玉没有？”众人不解其语，黛玉便忖度着因他有玉，故问我有也无，因答道：“我没有那个。想来那玉是一件罕物，岂能人人有的。”宝玉听了，登时发作起痴狂病来，摘下那玉，就狠命摔去，骂道：“什么罕物，连人之高低不择，还说‘通灵’不‘通灵’呢！我也不要这劳什子了！”吓的众人一拥争去拾玉。贾母急的搂了宝玉道：“孽障！你生气，要打骂人容易，何苦摔那命根子！”宝玉满面泪痕泣道：“家里姐姐妹妹都没有，单我有，我说没趣，如今来了这么一个神仙似的妹妹也没有，可知这不是个好东西。”贾母忙哄他道：“你这妹妹原有这个来的，因你姑妈去世时，舍不得你妹妹，无法处，遂将他的玉带了去了：一则全殉葬之礼，尽你妹妹之孝心；二则你姑妈之灵，亦可权作见了女儿之意。因此他只说没有这个，不便自己夸张之意。你如今怎比得他？还不好生慎重带上，仔细你娘知道了。”说着，便向丫鬟手中接来，亲与他带上。宝玉听如此说，想一想大有情理，也就不生别论了。\n\n　　当下，奶娘来请问黛玉之房舍。贾母说：“今将宝玉挪出来，同我在套间暖阁儿里，把你林姑娘暂安置碧纱橱里。等过了残冬，春天再与他们收拾房屋，另作一番安置罢。”宝玉道：“好祖宗，我就在碧纱橱外的床上很妥当，何必又出来闹的老祖宗不得安静。”贾母想了一想说：“也罢了。”每人一个奶娘并一个丫头照管，余者在外间上夜听唤。一面早有熙凤命人送了一顶藕合色花帐，并几件锦被缎褥之类。\n\n　　黛玉只带了两个人来：一个是自幼奶娘王嬷嬷，一个是十岁的小丫头，亦是自幼随身的，名唤作雪雁。贾母见雪雁甚小，一团孩气，王嬷嬷又极老，料黛玉皆不遂心省力的，便将自己身边的一个二等丫头，名唤鹦哥者与了黛玉。外亦如迎春等例，每人除自幼乳母外，另有四个教引嬷嬷，除贴身掌管钗钏褕沐两个丫鬟外，另有五六个洒扫房屋来往使役的小丫鬟。当下，王嬷嬷与鹦哥陪侍黛玉在碧纱橱内。宝玉之乳母李嬷嬷，并大丫鬟名唤袭人者，陪侍在外面大床上。\n\n　　原来这袭人亦是贾母之婢，本名珍珠。贾母因溺爱宝玉，生恐宝玉之婢无竭力尽忠之人，素喜袭人心地纯良，克尽职任，遂与了宝玉。宝玉因知他本姓花，又曾见旧人诗句上有“花气袭人”之句，遂回明贾母，更名袭人。这袭人亦有些痴处：服侍贾母时，心中眼中只有一个贾母；今与了宝玉，心中眼中又只有一个宝玉。只因宝玉性情乖僻，每每规谏宝玉，心中着实忧郁。\n\n　　是晚，宝玉李嬷嬷已睡了，他见里面黛玉和鹦哥犹未安息，他自卸了妆，悄悄进来，笑问：“姑娘怎么还不安息？”黛玉忙让：“姐姐请坐。”袭人在床沿上坐了。鹦哥笑道：“林姑娘正在这里伤心，自己淌眼抹泪的说：‘今儿才来，就惹出你家哥儿的狂病，倘或摔坏了那玉，岂不是因我之过！’因此便伤心，我好容易劝好了。”袭人道：“姑娘快休如此，将来只怕比这个更奇怪的笑话儿还有呢！若为他这种行止，你多心伤感，只怕你伤感不了呢。快别多心！”黛玉道：“姐姐们说的，我记着就是了。究竟那玉不知是怎么个来历？上面还有字迹？”袭人道：“连一家子也不知来历，上头还有现成的眼儿，听得说，落草时是从他口里掏出来的。等我拿来你看便知。”黛玉忙止道：“罢了，此刻夜深，明日再看也不迟。”大家又叙了一回，方才安歇。\n\n　　次日起来，省过贾母，因往王夫人处来，正值王夫人与熙凤在一处拆金陵来的书信看，又有王夫人之兄嫂处遣了两个媳妇来说话的。黛玉虽不知原委，探春等却都晓得是议论金陵城中所居的薛家姨母之子姨表兄薛蟠，倚财仗势，打死人命，现在应天府案下审理。如今母舅王子腾得了信息，故遣他家内的人来告诉这边，意欲唤取进京之意。');
INSERT INTO `book_content` VALUES (237, 21, 4, '第4章', '却说黛玉同姊妹们至王夫人处，见王夫人与兄嫂处的来使计议家务，又说姨母家遭人命官司等语。因见王夫人事情冗杂，姊妹们遂出来，至寡嫂李氏房中来了。\n\n　　原来这李氏即贾珠之妻。珠虽夭亡，幸存一子，取名贾兰，今方五岁，已入学攻书。这李氏亦系金陵名宦之女，父名李守中，曾为国子监祭酒，族中男女无有不诵诗读书者。至李守中继承以来，便说“女子无才便有德”，故生了李氏时，便不十分令其读书，只不过将些《女四书》，《列女传》，《贤媛集》等三四种书，使他认得几个字，记得前朝这几个贤女便罢了，却只以纺绩井臼为要，因取名为李纨，字宫裁。因此这李纨虽青春丧偶，居家处膏粱锦绣之中，竟如槁木死灰一般，一概无见无闻，唯知侍亲养子，外则陪侍小姑等针黹诵读而已。今黛玉虽客寄于斯，日有这般姐妹相伴，除老父外，余者也都无庸虑及了。\n\n　　如今且说雨村，因补授了应天府，一下马就有一件人命官司详至案下，乃是两家争买一婢，各不相让，以至殴伤人命。彼时雨村即传原告之人来审。那原告道：“被殴死者乃小人之主人。因那日买了一个丫头，不想是拐子拐来卖的。这拐子先已得了我家的银子，我家小爷原说第三日方是好日子，再接入门。这拐子便又悄悄的卖与薛家，被我们知道了，去找拿卖主，夺取丫头。无奈薛家原系金陵一霸，倚财仗势，众豪奴将我小主人竟打死了。凶身主仆已皆逃走，无影无踪，只剩了几个局外之人。小人告了一年的状，竟无人作主。望大老爷拘拿凶犯，剪恶除凶，以救孤寡，死者感戴天恩不尽！”\n\n　　雨村听了大怒道：“岂有这样放屁的事！打死人命就白白的走了，再拿不来的！”因发签差公人立刻将凶犯族中人拿来拷问，令他们实供藏在何处，一面再动海捕文书。正要发签时，只见案边立的一个门子使眼色儿，－－不令他发签之意。雨村心下甚为疑怪，只得停了手，即时退堂，至密室，侍从皆退去，只留门子服侍。这门子忙上来请安，笑问：“老爷一向加官进禄，八九年来就忘了我了？”雨村道：“却十分面善得紧，只是一时想不起来。”那门子笑道：“老爷真是贵人多忘事，把出身之地竟忘了，不记当年葫芦庙里之事？”雨村听了，如雷震一惊，方想起往事。原来这门子本是葫芦庙内一个小沙弥，因被火之后，无处安身，欲投别庙去修行，又耐不得清凉景况，因想这件生意倒还轻省热闹，遂趁年纪蓄了发，充了门子。雨村那里料得是他，便忙携手笑道：“原来是故人。”又让坐了好谈。这门子不敢坐。雨村笑道：“贫贱之交不可忘。你我故人也，二则此系私室，既欲长谈，岂有不坐之理？”这门子听说，方告了座，斜签着坐了。\n\n　　雨村因问方才何故有不令发签之意。这门子道：“老爷既荣任到这一省，难道就没抄一张本省‘护官符’来不成？”雨村忙问：“何为‘护官符’？我竟不知。”门子道：“这还了得！连这个不知，怎能作得长远！如今凡作地方官者，皆有一个私单，上面写的是本省最有权有势，极富极贵的大乡绅名姓，各省皆然，倘若不知，一时触犯了这样的人家，不但官爵，只怕连性命还保不成呢！所以绰号叫作‘护官符’。方才所说的这薛家，老爷如何惹他！他这件官司并无难断之处，皆因都碍着情分面上，所以如此。”一面说，一面从顺袋中取出一张抄写的‘护官符’来，递与雨村，看时，上面皆是本地大族名宦之家的谚俗口碑。其口碑排写得明白，下面所注的皆是自始祖官爵并房次。石头亦曾抄写了一张，今据石上所抄云：\n\n　　贾不假，白玉为堂金作马。（宁国荣国二公之后，共二十房分，宁荣亲派八房在都外，现原籍住者十二房。）\n\n　　阿房宫，三百里，住不下金陵一个史。（保龄侯尚书令史公之后，房分共十八，都中现住者十房，原籍现居八房。）\n\n　　东海缺少白玉床，龙王来请金陵王。（都太尉统制县伯王公之后，共十二房，都中二房，余在籍。）\n\n　　丰年好大雪，珍珠如土金如铁。（紫薇舍人薛公之后，现领内府帑银行商，共八房分。）\n\n　　雨村犹未看完，忽听传点，人报：“王老爷来拜。”雨村听说，忙具衣冠出去迎接。有顿饭工夫，方回来细问。这门子道：“这四家皆连络有亲，一损皆损，一荣皆荣，扶持遮饰，俱有照应的。今告打死人之薛，就系丰年大雪之‘雪’也。也不单靠这三家，他的世交亲友在都在外者，本亦不少。老爷如今拿谁去？”雨村听如此说，便笑问门子道：“如你这样说来，却怎么了结此案？你大约也深知这凶犯躲的方向了？”\n\n　　门子笑道：“不瞒老爷说，不但这凶犯的方向我知道，一并这拐卖之人我也知道，死鬼买主也深知道。待我细说与老爷听：这个被打之死鬼，乃是本地一个小乡绅之子，名唤冯渊，自幼父母早亡，又无兄弟，只他一个人守着些薄产过日子。长到十八九岁上，酷爱男风，不喜女色。这也是前生冤孽，可巧遇见这拐子卖丫头，他便一眼看上了这丫头，立意买来作妾，立誓再不交结男子，也不再娶第二个了，所以三日后方过门。谁晓这拐子又偷卖与薛家，他意欲卷了两家的银子，再逃往他省。谁知又不曾走脱，两家拿住，打了个臭死，都不肯收银，只要领人。那薛家公子岂是让人的，便喝着手下人一打，将冯公子打了个稀烂，抬回家去三日死了。这薛公子原是早已择定日子上京去的，头起身两日前，就偶然遇见这丫头，意欲买了就进京的，谁知闹出这事来。既打了冯公子，夺了丫头，他便没事人一般，只管带了家眷走他的路。他这里自有兄弟奴仆在此料理，也并非为此些些小事值得他一逃走的。这且别说，老爷你当被卖之丫头是谁？”雨村笑道：“我如何得知。”门子冷笑道：“这人算来还是老爷的大恩人呢！他就是葫芦庙旁住的甄老爷的小姐，名唤英莲的。”雨村罕然道：“原来就是他！闻得养至五岁被人拐去，却如今才来卖呢？”\n\n　　门子道：“这一种拐子单管偷拐五六岁的儿女，养在一个僻静之处，到十一二岁，度其容貌，带至他乡转卖。当日这英莲，我们天天哄他顽耍，虽隔了七八年，如今十二三岁的光景，其模样虽然出脱得齐整好些，然大概相貌，自是不改，熟人易认。况且他眉心中原有米粒大小的一点胭脂〈疒计〉，从胎里带来的，所以我却认得。偏生这拐子又租了我的房舍居住，那日拐子不在家，我也曾问他。他是被拐子打怕了的，万不敢说，只说拐子系他亲爹，因无钱偿债，故卖他。我又哄之再四，他又哭了，只说‘我不记得小时之事！’这可无疑了。那日冯公子相看了，兑了银子，拐子醉了，他自叹道：‘我今日罪孽可满了！’后又听见冯公子令三日之后过门，他又转有忧愁之态。我又不忍其形景，等拐子出去，又命内人去解释他：‘这冯公子必待好日期来接，可知必不以丫鬟相看。况他是个绝风流人品，家里颇过得，素习又最厌恶堂客，今竟破价买你，后事不言可知。只耐得三两日，何必忧闷！’他听如此说，方才略解忧闷，自为从此得所。谁料天下竟有这等不如意事，第二日，他偏又卖与薛家。若卖与第二个人还好，这薛公子的混名人称‘呆霸王’，最是天下第一个弄性尚气的人，而且使钱如土，遂打了个落花流水，生拖死拽，把个英莲拖去，如今也不知死活。这冯公子空喜一场，一念未遂，反花了钱，送了命，岂不可叹！”\n\n　　雨村听了，亦叹道：“这也是他们的孽障遭遇，亦非偶然。不然这冯渊如何偏只看准了这英莲？这英莲受了拐子这几年折磨，才得了个头路，且又是个多情的，若能聚合了，倒是件美事，偏又生出这段事来。这薛家纵比冯家富贵，想其为人，自然姬妾众多，淫佚无度，未必及冯渊定情于一人者。这正是梦幻情缘，恰遇一对薄命儿女。且不要议论他，只目今这官司，如何剖断才好？”门子笑道：“老爷当年何其明决，今日何反成了个没主意的人了！小的闻得老爷补升此任，亦系贾府王府之力，此薛蟠即贾府之亲，老爷何不顺水行舟，作个整人情，将此案了结，日后也好去见贾府王府。”雨村道：“你说的何尝不是。但事关人命，蒙皇上隆恩，起复委用，实是重生再造，正当殚心竭力图报之时，岂可因私而废法？是我实不能忍为者。”门子听了，冷笑道：“老爷说的何尝不是大道理，但只是如今世上是行不去的。岂不闻古人有云：‘大丈夫相时而动’，又曰‘趋吉避凶者为君子’。依老爷这一说，不但不能报效朝廷，亦且自身不保，还要三思为妥。”\n\n　　雨村低了半日头，方说道：“依你怎么样？”门子道：“小人已想了一个极好的主意在此：老爷明日坐堂，只管虚张声势，动文书发签拿人。原凶自然是拿不来的，原告固是定要将薛家族中及奴仆人等拿几个来拷问。小的在暗中调停，令他们报个暴病身亡，令族中及地方上共递一张保呈，老爷只说善能扶鸾请仙，堂上设下乩坛，令军民人等只管来看。老爷就说：‘乩仙批了，死者冯渊与薛蟠原因夙孽相逢，今狭路既遇，原应了结。薛蟠今已得了无名之病，被冯魂追索已死。其祸皆因拐子某人而起，拐之人原系某乡某姓人氏，按法处治，余不略及’等语。小人暗中嘱托拐子，令其实招。众人见乩仙批语与拐子相符，余者自然也都不虚了。薛家有的是钱，老爷断一千也可，五百也可，与冯家作烧埋之费。那冯家也无甚要紧的人，不过为的是钱，见有了这个银子，想来也就无话了。老爷细想此计如何？”雨村笑道：“不妥，不妥。等我再斟酌斟酌，或可压服口声。”二人计议，天色已晚，别无话说。\n\n　　至次日坐堂，勾取一应有名人犯，雨村详加审问，果见冯家人口稀疏，不过赖此欲多得些烧埋之费，薛家仗势倚情，偏不相让，故致颠倒未决。雨村便徇情枉法，胡乱判断了此案。冯家得了许多烧埋银子，也就无甚话说了。雨村断了此案，急忙作书信二封，与贾政并京营节度使王子腾，不过说“令甥之事已完，不必过虑”等语。此事皆由葫芦庙内之沙弥新门子所出，雨村又恐他对人说出当日贫贱时的事来，因此心中大不乐业，后来到底寻了个不是，远远的充发了他才罢。\n\n　　当下言不着雨村。且说那买了英莲打死冯渊的薛公子，亦系金陵人氏，本是书香继世之家。只是如今这薛公子幼年丧父，寡母又怜他是个独根孤种，未免溺爱纵容，遂至老大无成，且家中有百万之富，现领着内帑钱粮，采办杂料。这薛公子学名薛蟠，表字文起，五岁上就性情奢侈，言语傲慢。虽也上过学，不过略识几字，终日惟有斗鸡走马，游山玩水而已。虽是皇商，一应经济世事，全然不知，不过赖祖父之旧情分，户部挂虚名，支领钱粮，其余事体，自有伙计老家人等措办。寡母王氏乃现任京营节度使王子腾之妹，与荣国府贾政的夫人王氏，是一母所生的姊妹，今年方四十上下年纪，只有薛蟠一子。还有一女，比薛蟠小两岁，乳名宝钗，生得肌骨莹润，举止娴雅。当日有他父亲在日，酷爱此女，令其读书识字，较之乃兄竟高过十倍。自父亲死后，见哥哥不能依贴母怀，他便不以书字为事，只留心针黹家计等事，好为母亲分忧解劳。近因今上崇诗尚礼，征采才能，降不世出之隆恩，除聘选妃嫔外，凡仕宦名家之女，皆亲名达部，以备选为公主郡主入学陪侍，充为才人赞善之职。二则自薛蟠父亲死后，各省中所有的买卖承局，总管，伙计人等，见薛蟠年轻不谙世事，便趁时拐骗起来，京都中几处生意，渐亦消耗。薛蟠素闻得都中乃第一繁华之地，正思一游，便趁此机会，一为送妹待选，二为望亲，三因亲自入部销算旧帐，再计新支，----其实则为游览上国风光之意。因此早已打点下行装细软，以及馈送亲友各色土物人情等类，正择日一定起身，不想偏遇见了拐子重卖英莲。薛蟠见英莲生得不俗，立意买他，又遇冯家来夺人，因恃强喝令手下豪奴将冯渊打死。他便将家中事务一一的嘱托了族中人并几个老家人，他便带了母妹竟自起身长行去了。人命官司一事，他竟视为儿戏，自为花上几个臭钱，没有不了的。\n\n　　在路不记其日。那日已将入都时，却又闻得母舅王子腾升了九省统制，奉旨出都查边。薛蟠心中暗喜道：“我正愁进京去有个嫡亲的母舅管辖着，不能任意挥霍挥霍，偏如今又升出去了，可知天从人愿。”因和母亲商议道：“咱们京中虽有几处房舍，只是这十来年没人进京居住，那看守的人未免偷着租赁与人，须得先着几个人去打扫收拾才好。”他母亲道：“何必如此招摇！咱们这一进京，原该先拜望亲友，或是在你舅舅家，或是你姨爹家。他两家的房舍极是便宜的，咱们先能着住下，再慢慢的着人去收拾，岂不消停些。”薛蟠道：“如今舅舅正升了外省去，家里自然忙乱起身，咱们这工夫一窝一拖的奔了去，岂不没眼色。”他母亲道：“你舅舅家虽升了去，还有你姨爹家。况这几年来，你舅舅姨娘两处，每每带信捎书，接咱们来。如今既来了，你舅舅虽忙着起身，你贾家姨娘未必不苦留我们。咱们且忙忙收拾房屋，岂不使人见怪？你的意思我却知道，守着舅舅姨爹住着，未免拘紧了你，不如你各自住着，好任意施为。你既如此，你自去挑所宅子去住，我和你姨娘，姊妹们别了这几年，却要厮守几日，我带了你妹子投你姨娘家去，你道好不好？”薛蟠见母亲如此说，情知扭不过的，只得吩咐人夫一路奔荣国府来。\n\n　　那时王夫人已知薛蟠官司一事，亏贾雨村维持了结，才放了心。又见哥哥升了边缺，正愁又少了娘家的亲戚来往，略加寂寞。过了几日，忽家人传报：“姨太太带了哥儿姐儿，合家进京，正在门外下车。”喜的王夫人忙带了女媳人等，接出大厅，将薛姨妈等接了进去。姊妹们暮年相会，自不必说悲喜交集，泣笑叙阔一番。忙又引了拜见贾母，将人情土物各种酬献了。合家俱厮见过，忙又治席接风。\n\n　　薛蟠已拜见过贾政，贾琏又引着拜见了贾赦，贾珍等。贾政便使人上来对王夫人说：“姨太太已有了春秋，外甥年轻不知世路，在外住着恐有人生事。咱们东北角上梨香院一所十来间房，白空闲着，打扫了，请姨太太和姐儿哥儿住了甚好。”王夫人未及留，贾母也就遣人来说：“请姨太太就在这里住下，大家亲密些”等语。薛姨妈正要同居一处，方可拘紧些儿子，若另住在外，又恐他纵性惹祸，遂忙道谢应允。又私与王夫人说明：“一应日费供给一概免却，方是处常之法。”王夫人知他家不难于此，遂亦从其愿。从此后薛家母子就在梨香院住了。\n\n　　原来这梨香院即当日荣公暮年养静之所，小小巧巧，约有十余间房屋，前厅后舍俱全。另有一门通街，薛蟠家人就走此门出入。西南有一角门，通一夹道，出夹道便是王夫人正房的东边了。每日或饭后，或晚间，薛姨妈便过来，或与贾母闲谈，或与王夫人相叙。宝钗日与黛玉迎春姊妹等一处，或看书下棋，或作针黹，倒也十分乐业。\n\n　　只是薛蟠起初之心，原不欲在贾宅居住者，但恐姨父管约拘禁，料必不自在的，无奈母亲执意在此，且宅中又十分殷勤苦留，只得暂且住下，一面使人打扫出自己的房屋，再移居过去的。谁知自从在此住了不上一月的光景，贾宅族中凡有的子侄，俱已认熟了一半，凡是那些纨绔气习者，莫不喜与他来往，今日会酒，明日观花，甚至聚赌嫖娼，渐渐无所不至，引诱的薛蟠比当日更坏了十倍。虽然贾政训子有方，治家有法，一则族大人多，照管不到这些；二则现任族长乃是贾珍，彼乃宁府长孙，又现袭职，凡族中事，自有他掌管；三则公私冗杂，且素性潇洒，不以俗务为要，每公暇之时，不过看书着棋而已，馀事多不介意。况且这梨香院相隔两层房舍，又有街门另开，任意可以出入，所以这些子弟们竟可以放意畅怀的，因此遂将移居之念渐渐打灭了。');

-- ----------------------------
-- Table structure for chat_message
-- ----------------------------
DROP TABLE IF EXISTS `chat_message`;
CREATE TABLE `chat_message`  (
  `message_id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `sender_id` int NOT NULL,
  `receiver_id` int NOT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `msg_type` tinyint NULL DEFAULT 0 COMMENT '\'0文本,1图片,2表情,3文件,4系统\',',
  `status` tinyint NULL DEFAULT 0 COMMENT '\'0未读,1已读\'',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`message_id`) USING BTREE,
  INDEX `sender_id`(`sender_id` ASC) USING BTREE,
  INDEX `receiver_id`(`receiver_id` ASC) USING BTREE,
  INDEX `idx_session`(`session_id` ASC) USING BTREE,
  CONSTRAINT `chat_message_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `chat_session` (`session_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chat_message_ibfk_2` FOREIGN KEY (`sender_id`) REFERENCES `user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chat_message_ibfk_3` FOREIGN KEY (`receiver_id`) REFERENCES `user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of chat_message
-- ----------------------------

-- ----------------------------
-- Table structure for chat_session
-- ----------------------------
DROP TABLE IF EXISTS `chat_session`;
CREATE TABLE `chat_session`  (
  `session_id` bigint NOT NULL AUTO_INCREMENT,
  `user_a` int NOT NULL,
  `user_b` int NOT NULL,
  `last_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `last_time` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`session_id`) USING BTREE,
  UNIQUE INDEX `uniq_users`(`user_a` ASC, `user_b` ASC) USING BTREE,
  INDEX `user_b`(`user_b` ASC) USING BTREE,
  CONSTRAINT `chat_session_ibfk_1` FOREIGN KEY (`user_a`) REFERENCES `user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chat_session_ibfk_2` FOREIGN KEY (`user_b`) REFERENCES `user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

