-- ----------------------------
-- Table structure for song_lyric
-- ----------------------------
DROP TABLE IF EXISTS `song_lyric`;
CREATE TABLE `song_lyric`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `song_id` int NOT NULL COMMENT '关联的歌曲ID',
  `lyric_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '纯歌词文本（不带时间轴）',
  `lrc_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'LRC歌词（带时间轴）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_song`(`song_id` ASC) USING BTREE,
  CONSTRAINT `fk_song_lyric_song` FOREIGN KEY (`song_id`) REFERENCES `song` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '歌曲歌词表' ROW_FORMAT = DYNAMIC;

