-- ----------------------------
-- Table structure for user_notification
-- ----------------------------
DROP TABLE IF EXISTS `user_notification`;
CREATE TABLE `user_notification`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '被通知的用户ID',
  `from_user_id` int NOT NULL COMMENT '触发通知的用户ID',
  `comment_id` int NOT NULL COMMENT '关联的评论ID',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'reply' COMMENT '通知类型，例如 reply、like 等',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已读（0未读，1已读）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `fk_notification_comment`(`comment_id` ASC) USING BTREE,
  INDEX `idx_userid_isread_create`(`user_id` ASC, `is_read` ASC, `create_time` DESC) USING BTREE,
  CONSTRAINT `fk_notification_comment` FOREIGN KEY (`comment_id`) REFERENCES `book_comment` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

